window.DOSIK=window.DOSIK||{};DOSIK["sm_comm"]={"1":[{"t":"table","title":"상인의 종류 등","head":["구분","내용"],"rows":[["상인의 종류 · 당연상인","자기명의로 상행위를 하는 자"],["상인의 종류 · 의제상인","점포 등 설비에 의하여 상인적 방법으로 영업하는 자와 회사는 상행위를 하지 않더라도 상인으로 본다"],["상인의 종류 · 소상인","지배인·상호·상업장부·상업등기 규정은 소상인에게 적용하지 않는다(제9조)"],["미성년자·법정대리인 영업 · 미성년자 영업","미성년자가 법정대리인의 허락을 얻어 영업하면 등기하여야 하고, 허락을 얻어 무한책임사원이 되면 사원자격으로 한 행위에는 능력자로 본다"],["미성년자·법정대리인 영업 · 법정대리인 영업","법정대리인이 미성년자·피한정후견인·피성년후견인을 위하여 영업할 때도 등기한다"],["미성년자·법정대리인 영업 · 대리권 제한","법정대리인의 대리권 제한은 선의의 제3자에게 대항하지 못한다"],["지배인 · 권한","지배인은 영업주에 갈음하여 영업에 관한 재판상·재판외의 모든 행위를 하고, 지배인 아닌 사용인을 선임·해임할 수 있다"],["지배인 · 대리권 제한","대리권 제한은 선의의 제3자에게 대항하지 못한다"],["지배인 · 등기","선임과 대리권 소멸은 영업소(회사는 본점) 소재지에서 등기한다"]]},{"t":"table","title":"공동지배인·표현지배인 · 부분적 포괄대리권 사용인·점포 사용인","head":["구분","내용"],"rows":[["공동지배인·표현지배인 · 공동지배인","공동지배인에게 하는 의사표시는 지배인 1인에게 해도 영업주에게 효력이 있다"],["공동지배인·표현지배인 · 표현지배인","본부장·지점장 등 지배인으로 인정될 명칭을 쓰는 자는 지배인과 같은 권한이 있는 것으로 보지만 재판상 행위는 제외되고 상대방이 악의이면 적용하지 않는다"],["부분적 포괄대리권 사용인·점포 사용인 · 부분적 포괄대리권 사용인","영업의 특정한 종류나 사항을 위임받은 사용인은 그에 관한 재판외의 모든 행위를 할 수 있다(제15조)"],["부분적 포괄대리권 사용인·점포 사용인 · 점포 사용인","물건판매점포의 사용인은 판매에 관한 모든 권한이 있는 것으로 보되 상대방이 악의이면 그렇지 않다"]]},{"t":"table","title":"상업사용인의 경업·겸직 금지 · 상호","head":["구분","내용"],"rows":[["상업사용인의 경업·겸직 금지","상업사용인은 영업주의 허락 없이 영업부류에 속한 거래를 하거나 다른 회사의 무한책임사원·이사·다른 상인의 사용인이 되지 못한다 → 위반 거래가 자기 계산이면 영업주의 계산으로 볼 수 있고(개입권), 제3자 계산이면 이득의 양도를 청구한다 → 이 권리는 거래를 안 날부터 2주간, 거래가 있은 날부터 1년이 지나면 소멸한다"],["상호 · 회사 상호","회사 상호에는 종류에 따른 문자를 쓰고 회사가 아니면 회사임을 표시하는 문자를 쓰지 못한다"],["상호 · 등기 상호","타인이 등기한 상호는 같은 특별시·광역시·시·군에서 동종영업의 상호로 등기하지 못한다"],["상호 · 부정한 목적","같은 지역에서 동종영업으로 타인의 등기 상호를 쓰면 부정한 목적이 추정된다"],["상호 · 양도","상호는 영업을 폐지하거나 영업과 함께하는 경우에만 양도할 수 있고 양도는 등기해야 제3자에 대항한다"]]},{"t":"table","title":"명의대여자 책임·상호 폐지 간주 · 상업장부·상업등기","head":["구분","내용"],"rows":[["명의대여자 책임·상호 폐지 간주 · 명의대여자 책임","자기 성명이나 상호로 영업할 것을 허락한 자는 자기를 영업주로 오인하여 거래한 제3자에게 그 타인과 연대하여 변제할 책임을 진다(제24조)"],["명의대여자 책임·상호 폐지 간주 · 상호 폐지 간주","상호를 등기한 자가 정당한 사유 없이 2년간 쓰지 않으면 폐지한 것으로 본다"],["상업장부·상업등기 · 보존 기간","상업장부와 영업에 관한 중요서류는 10년, 전표류는 5년 보존하고 상업장부 기간은 폐쇄한 날부터 센다"],["상업장부·상업등기 · 등기 장소","등기할 사항은 영업소(회사는 본점) 소재지 관할 법원의 상업등기부에 등기하고, 2024.9.20 개정으로 지점 소재지 등기(제35조·제38조)는 삭제되었다"],["상업장부·상업등기 · 등기의 효력","등기 전에는 선의의 제3자에게 대항하지 못하고, 고의·과실로 사실과 다르게 등기한 자는 그 다름을 선의의 제3자에게 대항하지 못한다"]]}],"2":[{"t":"table","title":"양도인의 경업금지 · 상호속용 양수인의 책임","head":["구분","내용"],"rows":[["양도인의 경업금지 · 원칙","다른 약정이 없으면 양도인은 10년간 동일한 특별시·광역시·시·군과 인접 지역에서 동종영업을 하지 못한다(제41조 제1항)"],["양도인의 경업금지 · 약정","경업금지를 약정하면 같은 지역에 한하여 20년을 넘지 않는 범위에서 효력이 있다"],["상호속용 양수인의 책임 · 책임","양수인이 양도인의 상호를 계속 쓰면 양도인의 영업으로 인한 제3자의 채권에 대하여 양수인도 변제할 책임이 있다(제42조)"],["상호속용 양수인의 책임 · 면책","양수 후 지체 없이 책임이 없음을 등기하거나 양도인과 양수인이 제3자에게 그 뜻을 통지하면 책임을 지지 않는다"],["상호속용 양수인의 책임 · 변제","상호속용 때 채무자가 선의이며 중대한 과실 없이 양수인에게 변제하면 유효하다"]]},{"t":"table","title":"채무인수 광고·양도인 책임 소멸 · 주주총회 특별결의 대상","head":["구분","내용"],"rows":[["채무인수 광고·양도인 책임 소멸","상호를 계속 쓰지 않는 양수인도 양도인의 채무를 인수한다고 광고 → 양수인은 변제할 책임이 있다(제44조) → 양수인이 책임을 지는 경우 양도인의 제3자에 대한 채무는 영업양도 또는 광고 후 2년이 지나면 소멸한다"],["주주총회 특별결의 대상 · 특별결의를 거치는 경우(제374조 제1항)","영업의 전부 또는 중요한 일부의 양도 · 영업 전부의 임대·경영위임 · 타인과 영업의 손익 전부를 같이 하는 계약 · 회사 영업에 중대한 영향을 미치는 다른 회사의 영업 전부 또는 일부의 양수는 제434조의 특별결의를 거친다"],["주주총회 특별결의 대상 · 대상이 아닌 경우","영업 일부의 임대는 대상이 아니다"]]},{"t":"table","title":"반대주주의 주식매수청구 · 매수청구 대상이 아닌 결의","head":["구분","내용"],"rows":[["반대주주의 주식매수청구","반대주주는 의결권이 없거나 제한되는 주주를 포함하며 총회 전에 서면으로 반대 의사를 통지 → 결의일부터 20일 이내에 서면으로 매수를 청구 → 회사는 매수청구기간이 끝나는 날부터 2개월 이내에 매수 → 가격은 협의로 정하고 30일 이내에 협의가 안 되면 회사나 주주가 법원에 결정을 청구"],["매수청구 대상이 아닌 결의 · 매수청구권이 인정되지 않는 결의","이사의 해임 · 해산 후 회사 계속 결의 · 영업 일부의 임대"],["매수청구 대상이 아닌 결의 · 소규모합병","존속회사 주주만 매수청구를 못 한다 · 소멸회사 주주는 할 수 있다"]]},{"t":"table","title":"간이영업양도·양수·임대 · 사후설립","head":["구분","내용"],"rows":[["간이영업양도·양수·임대","총주주의 동의가 있거나 상대방이 그 회사 발행주식총수의 100분의 90 이상을 가지고 있음 → 주주총회 승인을 이사회 승인으로 갈음한다(제374조의3) → 이 경우 계약서 작성일부터 2주 이내에 공고나 통지를 하되 총주주 동의가 있으면 생략한다 · 공고·통지일부터 2주 이내에 서면으로 반대한 주주는 그 기간이 지난 날부터 20일 이내에 매수를 청구할 수 있다"],["사후설립","회사가 성립 후 2년 내에 성립 전부터 있던 영업용 재산을 자본금의 100분의 5 이상의 대가로 취득하는 계약을 하면 제374조를 준용하여 특별결의를 거친다(제375조)"]]}],"3":[{"t":"table","title":"기본적·보조적 상행위 등","head":["구분","내용"],"rows":[["기본적·보조적 상행위 · 기본적 상행위","영업으로 하는 매매, 임대차, 제조·가공, 운송·임치의 인수, 금융리스 등 제46조 각 호의 행위가 기본적 상행위이고, 오로지 임금을 받을 목적으로 제조하거나 노무에 종사하는 행위는 제외한다"],["기본적·보조적 상행위 · 보조적 상행위","상인이 영업을 위하여 하는 행위는 상행위로 보고, 상인의 행위는 영업을 위한 것으로 추정한다(제47조)"],["기본적·보조적 상행위 · 적용","당사자 한쪽에게만 상행위여도 전원에게 상법을 적용한다(제3조)"],["상행위의 대리·위임 · 대리인","상행위의 대리인은 본인을 위한 것임을 표시하지 않아도 본인에게 효력이 생기고, 상대방이 그 사정을 몰랐으면 대리인에게도 이행을 청구할 수 있다(제48조)"],["상행위의 대리·위임 · 대리권","상인이 영업에 관하여 준 대리권은 본인의 사망으로 소멸하지 않는다"],["청약·낙부통지·견품 보관 · 대화자 간","대화자 간의 청약은 상대방이 즉시 승낙하지 않으면 효력을 잃는다"],["청약·낙부통지·견품 보관 · 낙부통지","상시 거래관계에 있는 자로부터 영업부류의 청약을 받은 상인은 지체 없이 낙부의 통지를 발송하고, 하지 않으면 승낙한 것으로 본다(제53조)"],["청약·낙부통지·견품 보관 · 견품","청약과 함께 받은 견품은 청약을 거절해도 청약자의 비용으로 보관한다"]]},{"t":"table","title":"법정이율·이자·보수 · 다수채무자·보증인의 연대","head":["구분","내용"],"rows":[["법정이율·이자·보수 · 법정이율","상행위로 인한 채무의 법정이율은 연 6분이다(제54조)"],["법정이율·이자·보수 · 이자","상인이 영업에 관하여 금전을 대여하면 약정이 없어도 법정이자를 청구한다"],["법정이율·이자·보수 · 보수","영업범위 안에서 타인을 위하여 한 행위에는 상당한 보수를 청구할 수 있다"],["법정이율·이자·보수 · 임치","영업범위 안에서 임치를 받은 상인은 보수가 없어도 선량한 관리자의 주의를 한다"],["다수채무자·보증인의 연대 · 다수채무자","여럿이 그 1인 또는 전원에게 상행위가 되는 행위로 채무를 지면 연대하여 변제할 책임이 있다(제57조 제1항)"],["다수채무자·보증인의 연대 · 보증인","보증이 상행위이거나 주채무가 상행위로 인한 것이면 주채무자와 보증인이 연대한다"]]},{"t":"table","title":"상사유치권·유질 허용 · 상사시효","head":["구분","내용"],"rows":[["상사유치권·유질 허용 · 요건","상인 간의 상행위로 생긴 채권이 변제기에 있으면 채권자는 채무자에 대한 상행위로 점유하는 채무자 소유의 물건이나 유가증권을 유치할 수 있다(제58조)"],["상사유치권·유질 허용 · 견련성","피담보채권과 목적물 사이의 견련성은 필요 없다"],["상사유치권·유질 허용 · 배제","다른 약정으로 배제할 수 있다"],["상사유치권·유질 허용 · 유질","상행위로 생긴 채권을 담보하는 질권에는 유질계약 금지(민법 제339조)가 적용되지 않는다"],["상사시효","상행위로 인한 채권은 상법에 다른 규정이 없으면 5년간 행사하지 않으면 소멸시효가 완성되고, 다른 법령에 더 짧은 시효가 있으면 그에 따른다(제64조)"]]},{"t":"table","title":"상사매매 특칙 · 상호계산·익명조합","head":["구분","내용"],"rows":[["상사매매 특칙 · 수령 거부","상인 간 매매에서 매수인이 수령을 거부하면 매도인은 공탁하거나 상당한 기간을 정해 최고한 뒤 경매할 수 있다"],["상사매매 특칙 · 확정기매매","이행시기가 지난 뒤 상대방이 즉시 이행을 청구하지 않으면 해제한 것으로 본다"],["상사매매 특칙 · 검사·통지","매수인은 수령 후 지체 없이 검사하여 하자·수량부족을 즉시 통지해야 한다"],["상사매매 특칙 · 즉시 발견할 수 없는 하자","6월 내에 발견해 통지해야 해제·감액·손해배상을 청구할 수 있다"],["상사매매 특칙 · 악의","매도인이 악의이면 이 통지의무가 적용되지 않는다"],["상호계산·익명조합 · 상호계산","기간을 정하지 않으면 6월 · 계산서를 승인하면 착오나 탈루가 없는 한 각 항목에 이의하지 못한다"],["상호계산·익명조합 · 익명조합","익명조합원이 출자한 재산은 영업자의 재산으로 본다 · 익명조합원은 제3자에게 권리·의무가 없다 · 다만 자기 성명이나 상호를 영업자의 상호로 쓰게 하면 그 이후 채무에 대하여 영업자와 연대책임을 진다"]]}],"4":[{"t":"table","title":"대리상 등","head":["구분","내용"],"rows":[["대리상 · 뜻","대리상은 상업사용인이 아니면서 일정한 상인을 위하여 상시 그 영업부류의 거래를 대리하거나 중개하는 자다"],["대리상 · 경업금지","본인의 허락 없이 영업부류 거래를 하거나 동종영업 회사의 무한책임사원·이사가 되지 못한다"],["대리상 · 해지","존속기간 약정이 없으면 2월 전에 예고하고 해지할 수 있다"],["대리상의 보상청구권·유치권 · 보상청구권","대리상의 활동으로 새 고객이나 거래 증가가 생겨 계약 종료 후에도 본인이 이익을 얻으면 대리상은 상당한 보상을 청구할 수 있다"],["대리상의 보상청구권·유치권 · 보상액","종료 전 5년간의 평균연보수액을 넘지 못한다"],["대리상의 보상청구권·유치권 · 소멸","청구권은 계약이 종료한 날부터 6월이 지나면 소멸한다"],["대리상의 보상청구권·유치권 · 유치권","본인을 위하여 점유하는 물건이면 되고 본인 소유일 필요가 없다"],["중개인 · 지급","중개인은 다른 약정이나 관습이 없으면 중개한 행위에 관하여 당사자를 위한 지급을 받지 못한다"],["중개인 · 결약서","계약이 성립하면 결약서를 작성해 각 당사자에게 교부하고, 이 절차를 마치지 않으면 보수를 청구하지 못한다"],["중개인 · 보수","보수는 당사자 쌍방이 균분하여 부담한다"],["중개인 · 성명 묵비","당사자 일방의 성명을 표시하지 않은 중개인은 상대방에게 이행책임을 진다"]]},{"t":"table","title":"위탁매매인 · 운송주선인·운송인의 책임","head":["구분","내용"],"rows":[["위탁매매인 · 뜻","자기명의로 타인의 계산으로 물건이나 유가증권의 매매를 영업으로 하며 상대방에게 직접 권리를 취득하고 의무를 진다"],["위탁매매인 · 귀속","위탁매매로 취득한 물건·채권은 위탁자와 위탁매매인의 채권자 사이에서 위탁자의 소유나 채권으로 본다"],["위탁매매인 · 이행담보책임","다른 약정이 없으면 상대방의 채무불이행에 대하여 이행담보책임을 진다"],["위탁매매인 · 개입권","거래소 시세가 있는 물건은 직접 매도인·매수인이 되는 개입권이 있다"],["운송주선인·운송인의 책임 · 책임","주의를 게을리하지 않았음을 증명하지 못하면 운송물의 멸실·훼손·연착 손해를 배상한다"],["운송주선인·운송인의 책임 · 고가물","화폐·유가증권 등 고가물은 송하인이 종류와 가액을 명시한 경우에만 운송인이 책임진다"],["운송주선인·운송인의 책임 · 배상액","전부멸실·연착이면 인도할 날, 일부멸실·훼손이면 인도한 날의 도착지 가격으로 정한다"],["운송주선인·운송인의 책임 · 고의·중과실","모든 손해를 배상한다"]]},{"t":"table","title":"화물상환증·창고증권 · 책임 소멸·시효","head":["구분","내용"],"rows":[["화물상환증·창고증권 · 양도","기명식이어도 배서로 양도할 수 있고 이와 상환하지 않으면 운송물 인도를 청구하지 못한다"],["화물상환증·창고증권 · 선의 소지인","선의로 취득한 소지인에게 운송인은 증권에 적힌 대로 운송물을 수령한 것으로 보고 책임진다"],["화물상환증·창고증권 · 물권적 효력","증권을 교부하면 운송물을 인도한 것과 같은 물권적 효력이 있다"],["화물상환증·창고증권 · 창고증권","이 규정은 창고증권에 준용한다"],["책임 소멸·시효 · 책임 소멸","수하인이 유보 없이 운송물을 수령하고 운임을 지급하면 운송인의 책임이 소멸하되, 즉시 발견할 수 없는 훼손은 수령일부터 2주간 내에 통지하면 유지된다"],["책임 소멸·시효 · 1년","운송주선인·운송인·창고업자의 책임은 1년이 지나면 시효로 소멸"],["책임 소멸·시효 · 6개월","공중접객업자의 책임은 6개월이 지나면 시효로 소멸"],["책임 소멸·시효 · 악의","악의이면 적용하지 않는다"]]},{"t":"table","title":"공중접객업·창고업 · 금융리스·가맹·채권매입","head":["구분","내용"],"rows":[["공중접객업·창고업 · 휴대물","공중접객업자는 임치받지 않은 휴대물도 자기나 사용인의 과실로 멸실·훼손되면 배상하고, 책임이 없음을 알렸어도 면하지 못한다"],["공중접객업·창고업 · 고가물","고객이 종류와 가액을 명시하여 임치하지 않으면 책임이 없다"],["공중접객업·창고업 · 창고업자","임치기간 약정이 없으면 받은 날부터 6월이 지난 뒤 2주간 전에 예고하고 반환할 수 있다"],["금융리스·가맹·채권매입 · 금융리스이용자","물건을 수령함과 동시에 리스료를 지급하고, 공급이 계약대로 되지 않으면 공급자에게 직접 손해배상이나 인도를 청구하며 중대한 사정변경이 있으면 3개월 전에 예고하고 해지할 수 있다"],["금융리스·가맹·채권매입 · 가맹업자","다른 약정이 없으면 가맹상의 영업지역에서 동일·유사 업종 영업을 하지 못하고 특별한 사유가 없으면 가맹상의 영업양도에 동의해야 한다"],["금융리스·가맹·채권매입 · 채권매입업자","다른 약정이 없으면 영업채권 채무자가 이행하지 않을 때 계약 상대방에게 상환을 청구한다"]]}],"5":[{"t":"table","title":"회사의 개념·종류·해산명령 등","head":["구분","내용"],"rows":[["회사의 개념·종류·해산명령 · 개념","상행위나 그 밖의 영리를 목적으로 설립한 법인"],["회사의 개념·종류·해산명령 · 종류","합명·합자·유한책임·주식·유한회사의 5종이다(상호회사는 아니다)"],["회사의 개념·종류·해산명령 · 사원 수","주식회사·유한회사·유한책임회사는 사원 1인으로 설립할 수 있고 합명·합자회사는 2인 이상이 필요하다"],["회사의 개념·종류·해산명령 · 해산명령","설립목적이 불법하거나 정당한 사유 없이 설립 후 1년 내 영업을 개시하지 않거나 1년 이상 휴지하면 법원은 청구 또는 직권으로 해산을 명할 수 있다"],["회사의 능력·주소·성립 · 권리능력","성질·법령·정관상 목적에 의하여 제한되어 친권·상속은 누릴 수 없으나 유증은 받을 수 있고 명예권·상호권은 가진다"],["회사의 능력·주소·성립 · 사원 자격","다른 회사의 무한책임사원이 되지 못하지만 주주, 유한책임사원, 유한책임회사의 업무집행자는 될 수 있다"],["회사의 능력·주소·성립 · 주소·성립","주소는 본점소재지이고 본점소재지에서 설립등기를 함으로써 성립하며 해산 후에도 청산 목적 범위에서 권리능력이 남는다"],["발기인의 책임 · 주식 인수·납입","성립 후 인수되지 않은 주식이나 청약이 취소된 주식은 발기인이 공동으로 인수한 것으로 보고, 납입 미완료 주식은 발기인이 연대하여 납입하며 이 담보책임은 총주주의 동의로도 면제되지 않는다"],["발기인의 책임 · 임무해태","회사에 대한 손해배상책임은 총주주의 동의로 면제할 수 있고, 제3자에 대한 책임은 악의 또는 중대한 과실이 있을 때만 진다"],["발기인의 책임 · 설립비용","회사가 성립하지 못하면 설립비용은 발기인이 부담한다"],["발기인의 책임 · 찬조자","주식청약서에 설립 찬조의 뜻을 적도록 승낙한 자도 발기인과 같은 책임을 진다"]]},{"t":"table","title":"정관의 절대적 기재사항·효력 · 변태설립사항","head":["구분","내용"],"rows":[["정관의 절대적 기재사항·효력 · 절대적 기재사항","목적, 상호, 발행할 주식의 총수, 액면주식 1주의 금액, 설립 시 발행 주식총수, 본점 소재지, 공고 방법, 발기인의 성명·주민등록번호·주소이고 발기인 전원이 기명날인 또는 서명한다(제289조)"],["정관의 절대적 기재사항·효력 · 효력","정관은 공증인의 인증으로 효력이 생기지만 자본금 10억원 미만 회사를 발기설립하면 발기인의 기명날인·서명만으로 효력이 생긴다"],["정관의 절대적 기재사항·효력 · 정함이 없는 사항","설립 때 발행하는 주식의 종류와 수, 액면 이상 발행의 수·금액, 무액면주식의 발행가액과 자본금 계상액은 정관에 정함이 없으면 발기인 전원의 동의로 정한다"],["변태설립사항 · 종류","발기인의 특별이익, 현물출자, 재산인수(성립 후 양수할 재산의 종류·수량·가격·양도인 성명), 설립비용과 발기인 보수액은 정관에 적어야 효력이 있다(제290조)"],["변태설립사항 · 적지 않으면","그 약정만 무효이고 정관 전체가 무효가 되지는 않는다"],["변태설립사항 · 사후설립","변태설립사항이 아니라 주주총회 특별결의 사항이다"]]},{"t":"table","title":"설립무효의 소 · 발기설립 절차","head":["구분","내용"],"rows":[["설립무효의 소 · 주식회사","설립취소의 소가 없고, 설립무효는 주주·이사·감사만 회사성립일부터 2년 내에 본점소재지 지방법원에 소로써 주장한다(제328조)"],["설립무효의 소 · 판결","대세효가 있으나 소급효가 없어 확정 전의 법률관계는 유지되고, 패소한 원고는 악의 또는 중대한 과실이 있을 때만 회사에 연대하여 배상한다"],["설립무효의 소 · 제소권자","합명회사는 사원, 유한책임회사는 사원과 업무집행자, 유한회사는 사원·이사·감사가 제기한다"],["발기설립 절차","각 발기인은 서면으로 주식을 인수하고 인수가액 전액을 납입 → 이사·감사는 발기인의 의결권(인수주식 1주에 1개) 과반수로 선임 → 변태설립사항이 있으면 이사가 검사인 선임을 법원에 청구하고, 법원의 변경에 불복하는 발기인은 주식인수를 취소할 수 있다 → 자본금 10억원 미만 발기설립은 납입금보관증명서를 잔고증명서로 대신할 수 있다"]]},{"t":"table","title":"검사인 조사 대체·면제 · 모집설립·창립총회","head":["구분","내용"],"rows":[["검사인 조사 대체·면제 · 대체","특별이익과 설립비용·보수액은 공증인의 조사·보고로, 현물출자와 재산인수는 공인된 감정인의 감정으로 검사인 조사를 갈음하고 결과는 법원에 보고한다(제299조의2)"],["검사인 조사 대체·면제 · 면제","현물출자·재산인수 총액이 자본금의 5분의 1과 5천만원을 넘지 않는 등의 경우에는 검사인 조사가 필요 없다"],["검사인 조사 대체·면제 · 참가 제한","발기인이었던 자, 현물출자자, 재산인수 당사자인 이사·감사는 설립 조사·보고에 참가하지 못한다"],["모집설립·창립총회","주식 총수가 인수되면 발기인이 인수가액 전액을 납입 → 미납 인수인에게 기일의 2주간 전에 실권예고를 통지해 그 기일까지 납입하지 않아야 권리를 잃는다 → 변태설립사항은 발기인이 검사인 선임을 청구하고 창립총회가 변경하며, 납입금 보관자·장소 변경은 법원 허가를 받는다 → 창립총회 결의는 출석 인수인 의결권의 3분의 2 이상이며 인수된 주식 총수의 과반수로 하고, 소집통지에 없어도 정관변경·설립폐지를 결의할 수 있다"]]}],"6":[{"t":"table","title":"액면·무액면주식과 주주의 책임 등","head":["구분","내용"],"rows":[["액면·무액면주식과 주주의 책임 · 무액면주식","정관으로 정하면 주식의 전부를 무액면주식으로 발행할 수 있다(액면주식과 혼용 불가)"],["액면·무액면주식과 주주의 책임 · 액면주식","액면주식 1주의 금액은 100원 이상이고 주식 분할은 주주총회 특별결의로 하되 분할 후에도 100원 미만으로 하지 못한다"],["액면·무액면주식과 주주의 책임 · 전환","액면·무액면 사이의 전환으로는 자본금이 바뀌지 않아 채권자보호절차가 없다"],["액면·무액면주식과 주주의 책임 · 주주의 책임","주주의 책임은 주식의 인수가액을 한도로 한다"],["액면·무액면주식과 주주의 책임 · 공유","주식 공유자는 권리를 행사할 자 1인을 정하며 그가 없으면 회사의 통지는 공유자 1인에게 하면 된다"],["종류주식 · 종류","이익배당, 잔여재산분배, 의결권 배제·제한, 상환, 전환에 관하여 내용이 다른 종류주식을 정관에 정하여 발행한다"],["종류주식 · 의결권 배제·제한","발행주식총수의 4분의 1을 넘지 못한다(초과해도 당연무효가 아니라 지체 없이 시정 조치)"],["종류주식 · 상환주식","상환·전환 외의 종류주식으로만 발행하고 상환 대가로 현금·유가증권·자산을 줄 수 있으나 다른 종류주식은 주지 못한다"],["종류주식 · 상환 절차","회사가 상환하려면 취득일 2주 전에 통지하되 공고로 갈음할 수 있고 상환해도 자본금은 줄지 않는다"],["전환주식 · 효력 발생","주주가 전환을 청구하면 청구한 때, 회사가 전환하면 주권제출기간이 끝난 때 효력이 생긴다"],["전환주식 · 신주식","전환으로 발행하는 신주식의 발행가액은 전환 전 주식의 발행가액이고 새로 발행할 주식 수는 전환기간 동안 발행을 유보한다"],["전환주식 · 의결권","주주명부 폐쇄기간 중에 전환된 주식은 그 기간 중의 총회에서 의결권을 행사하지 못한다"]]},{"t":"table","title":"주권과 불소지·재발행 · 주식양도와 주권발행 전 양도","head":["구분","내용"],"rows":[["주권과 불소지·재발행 · 발행","주권은 회사 성립 후 또는 신주 납입기일 후 지체 없이 발행하고 그 전에 발행한 주권은 무효다"],["주권과 불소지·재발행 · 불소지","주주는 정관에 다른 정함이 없으면 주권 발행 전후를 가리지 않고 불소지 신고를 할 수 있고, 이미 발행된 주권은 회사에 제출한다"],["주권과 불소지·재발행 · 재발행","주권을 잃은 자는 공시최고를 거쳐 제권판결을 받아야 재발행을 청구한다"],["주권과 불소지·재발행 · 선의취득","위조 주권·무효 처리된 주권은 선의취득의 대상이 아니다"],["주식양도와 주권발행 전 양도 · 발행 후","주권 발행 후의 양도는 주권을 교부해야 하고 주권 점유자는 적법한 소지인으로 추정된다"],["주식양도와 주권발행 전 양도 · 발행 전","주권 발행 전 양도는 회사에 효력이 없으나 회사 성립 후 또는 신주 납입기일 후 6월이 지나면 의사표시만으로 회사에 효력이 있다"],["주식양도와 주권발행 전 양도 · 하자 치유","6월 전 양도도 그 뒤 6월이 지나도록 주권이 발행되지 않으면 하자가 치유된다"],["주식양도와 주권발행 전 양도 · 권리주","주식인수로 인한 권리(권리주)의 양도는 회사에 효력이 없다"]]},{"t":"table","title":"명의개서·주주명부 · 정관상 양도제한","head":["구분","내용"],"rows":[["명의개서·주주명부 · 대항력","취득자의 성명·주소를 주주명부에 적지 않으면 회사에 대항하지 못하고 회사가 양수 사실을 알아도 같다"],["명의개서·주주명부 · 청구","주권을 제시한 양수인은 단독으로 명의개서를 청구할 수 있다"],["명의개서·주주명부 · 폐쇄·기준일","폐쇄기간은 3월을 넘지 못하고 기준일은 권리행사일 전 3월 내의 날로 정하며 2주간 전에 공고하되 정관에 정했으면 공고가 필요 없다"],["명의개서·주주명부 · 비치","주주명부는 본점에 두고 명의개서대리인을 둔 때에는 그 영업소에도 둘 수 있다"],["정관상 양도제한","정관으로 주식 양도에 이사회 승인을 받게 할 수 있고, 승인 없는 양도는 회사에 효력이 없지만 당사자 사이에서는 유효 → 회사는 승인 청구일부터 1월 내에 서면으로 통지 → 거부 통지를 받은 주주는 20일 내에 상대방 지정이나 주식매수를 청구 → 이사회가 지정 청구일부터 2주간 내에 지정 통지를 하지 않거나 지정된 자가 10일 내에 매도청구를 하지 않으면 양도를 승인한 것으로 보며, 양수인도 취득 승인을 청구할 수 있다"]]},{"t":"table","title":"자기주식 취득·처분·소각 · 주식매수선택권·지배주주 매도청구","head":["구분","내용"],"rows":[["자기주식 취득·처분·소각 · 취득","회사는 직전 결산기 배당가능이익 한도에서 자기 명의와 계산으로 거래소 매수나 균등 조건으로 취득하고, 취득가액 한도 등은 주주총회 결의로 정하되 이사회 결의로 이익배당을 할 수 있는 회사는 이사회 결의로 정한다"],["자기주식 취득·처분·소각 · 예외 취득","합병·영업 전부 양수, 권리 실행, 단주 처리, 주식매수청구권 행사의 경우에는 배당가능이익과 관계없이 취득할 수 있다"],["자기주식 취득·처분·소각 · 자회사","자회사는 합병·주식교환·이전, 영업 전부 양수, 권리 실행의 경우에만 모회사 주식을 취득해 6월 내에 처분한다"],["자기주식 취득·처분·소각 · 처분·소각","처분은 정관에 정함이 없으면 이사회가 정하고 이사회 결의로 자기주식을 소각하면 자본금 감소 절차가 필요 없다"],["자기주식 취득·처분·소각 · 질취","질취는 발행주식총수의 20분의 1을 넘지 못한다"],["주식매수선택권·지배주주 매도청구 · 부여","정관에 근거를 두고 주주총회 특별결의로 부여하고, 10% 이상 주주, 경영에 사실상 영향력을 행사하는 자와 그 배우자·직계존비속에게는 줄 수 없고 행사로 발행·양도할 주식은 발행주식총수의 10%를 넘지 못한다"],["주식매수선택권·지배주주 매도청구 · 행사","결의일부터 2년 이상 재임·재직해야 행사하고, 양도할 수 없으나 상속인은 행사할 수 있으며 신주 발행 시 행사가액은 부여일 기준 실질가액과 권면액 중 높은 금액 이상이다"],["주식매수선택권·지배주주 매도청구 · 지배주주 매도청구","발행주식총수의 95% 이상을 가진 지배주주는 주주총회 승인을 받아 소수주주에게 매도를 청구하고, 소수주주는 2개월 내에 매도하며 대금을 지급한 때 주식이 이전된다"]]}],"7":[{"t":"table","title":"소집 결정·통지 등","head":["구분","내용"],"rows":[["소집 결정·통지 · 결정","총회 소집은 상법에 다른 규정이 없으면 이사회가 정한다"],["소집 결정·통지 · 통지","총회일 2주 전에 각 주주에게 서면으로 통지하거나 각 주주의 동의를 받아 전자문서로 통지하며 통지서에는 회의의 목적사항을 적는다"],["소집 결정·통지 · 3년 미도달","통지가 주주명부상 주소에 계속 3년간 도달하지 않으면 그 주주에게 통지하지 않을 수 있다"],["소집 결정·통지 · 의결권 없는 주주","통지하지 않지만 주식매수청구권이 인정되는 안건이 있으면 통지한다"],["소집지·연기·철회 · 소집지","총회는 정관에 달리 정한 바가 없으면 본점소재지나 인접한 곳에 소집한다(제364조)"],["소집지·연기·철회 · 연기·속행","총회에서 연기나 속행을 결의하면 다시 소집절차를 밟지 않는다"],["소집지·연기·철회 · 철회","소집 철회는 이사회 결의를 거쳐 대표이사가 소집과 같은 방법으로 통지한다"],["자본금 10억원 미만 회사의 특례 · 통지","총회일 10일 전에 서면 또는 각 주주 동의를 받은 전자문서로 통지할 수 있다"],["자본금 10억원 미만 회사의 특례 · 전원 동의","주주 전원의 동의가 있으면 소집절차 없이 총회를 열 수 있고 서면결의로 결의를 갈음할 수 있다"],["자본금 10억원 미만 회사의 특례 · 서면결의","목적사항에 주주 전원이 서면으로 동의하면 서면결의가 있는 것으로 본다(과반수 동의로는 안 된다)"]]},{"t":"table","title":"소수주주의 소집청구·주주제안 · 결의요건과 의결권 계산","head":["구분","내용"],"rows":[["소수주주의 소집청구·주주제안 · 소집청구","발행주식총수의 3% 이상 주주는 목적사항과 소집 이유를 적은 서면으로 이사회에 임시총회 소집을 청구하고, 지체 없이 절차를 밟지 않으면 법원의 허가를 받아 직접 소집한다"],["소수주주의 소집청구·주주제안 · 감사","감사도 서면으로 이사회에 임시총회 소집을 청구할 수 있다"],["소수주주의 소집청구·주주제안 · 주주제안","의결권 없는 주식을 뺀 3% 이상 주주는 총회일 6주 전에 이사에게 서면·전자문서로 주주제안을 한다"],["소수주주의 소집청구·주주제안 · 이사회","이사회는 법령·정관 위반 등 제외사유가 없으면 이를 목적사항으로 하며 청구가 있으면 설명 기회를 준다"],["결의요건과 의결권 계산 · 결의요건","보통결의는 출석 의결권의 과반수와 발행주식총수의 4분의 1 이상 · 특별결의는 출석 의결권의 3분의 2 이상과 발행주식총수의 3분의 1 이상"],["결의요건과 의결권 계산 · 의결권 계산","자기주식, 의결권 없는 종류주식, 10분의 1 초과 상호보유로 의결권이 없는 주식은 발행주식총수에 넣지 않는다 · 특별이해관계인의 주식과 감사 선임 때 3%를 넘는 부분은 출석 의결권 수에 넣지 않는다"]]},{"t":"table","title":"특별결의 사항 · 의결권 행사방법","head":["구분","내용"],"rows":[["특별결의 사항 · 특별결의 사항","정관변경, 영업양도 등(제374조), 사후설립 · 이사·감사 해임, 주식매수선택권 부여, 주식분할 · 임의해산, 회사 계속, 휴면회사 계속 · 주식교환·이전, 합병·분할"],["특별결의 사항 · 다른 결의","재무제표 승인과 총회의 검사인 선임은 보통결의이고 중간배당은 이사회가 정한다 · 이사·발기인의 회사에 대한 책임 면제와 주식회사의 유한책임회사 조직변경은 총주주의 동의가 있어야 한다"],["의결권 행사방법 · 대리","대리인은 대리권을 증명하는 서면 또는 전자문서를 총회에 제출하고, 판례상 서면은 원본이어야 한다"],["의결권 행사방법 · 서면·전자투표","서면투표는 정관에 정함이 있어야 하고 전자투표는 이사회 결의로 정하며 같은 주식에 대해서는 둘 중 하나만 선택한다"],["의결권 행사방법 · 불통일행사","총회일 3일 전에 서면·전자문서로 그 뜻과 이유를 통지하고, 주식의 신탁을 인수하는 등 타인을 위하여 주식을 가진 경우가 아니면 회사가 거부할 수 있다"]]},{"t":"table","title":"결의취소의 소 · 무효·부존재·부당결의","head":["구분","내용"],"rows":[["결의취소의 소 · 사유","소집절차·결의방법이 법령·정관에 위반하거나 현저히 불공정한 때와 결의내용이 정관에 위반한 때"],["결의취소의 소 · 제소권자·기간","주주·이사·감사가 결의일부터 2월 내에 제기한다(회사채권자는 제기 못 함)"],["결의취소의 소 · 담보 제공","주주가 제소하면 회사의 청구로 담보 제공을 명할 수 있으나 그 주주가 이사·감사이면 명하지 못한다"],["결의취소의 소 · 재량기각·효력","법원은 결의 내용, 회사 현황 등을 참작해 재량기각할 수 있고 인용판결은 대세효와 소급효가 있다"],["무효·부존재·부당결의 · 결의무효확인의 소","결의내용이 법령에 위반하면 제기한다"],["무효·부존재·부당결의 · 결의부존재확인의 소","소집절차·결의방법의 하자가 결의가 존재한다고 볼 수 없을 정도로 중대하면 제기하고 둘 다 제소기간 제한이 없으며 판결에 소급효가 있다"],["무효·부존재·부당결의 · 부당결의 취소·변경의 소","특별이해관계로 의결권을 행사하지 못한 주주는 결의가 현저히 부당하고 행사했으면 저지할 수 있었을 때 결의일부터 2월 내에 제기하며 이 소에는 재량기각이 없다"],["무효·부존재·부당결의 · 등기","결의사항이 등기된 경우 판결이 확정되면 본점 소재지에서 등기한다"]]}],"8":[{"t":"table","title":"이사의 선임·원수·임기 등","head":["구분","내용"],"rows":[["이사의 선임·원수·임기 · 선임","이사는 주주총회에서 선임하고 선임결의와 본인의 승낙으로 지위를 얻고, 회사와 이사의 관계에는 위임 규정을 준용한다"],["이사의 선임·원수·임기 · 원수","이사는 3명 이상이지만 자본금 10억원 미만 회사는 1명 또는 2명으로 할 수 있다"],["이사의 선임·원수·임기 · 임기","임기는 3년을 넘지 못하되 정관으로 임기 중 최종 결산기에 관한 정기총회 종결 때까지 늘릴 수 있다"],["이사의 선임·원수·임기 · 자격주·보수","정관으로 정한 자격주는 감사에게 공탁하고, 보수는 정관에 없으면 주주총회가 정한다"],["해임·결원·직무대행자 · 해임","이사는 언제든지 주주총회 특별결의로 해임할 수 있고, 임기를 정한 이사를 정당한 이유 없이 만료 전에 해임하면 손해배상을 청구할 수 있다(임기를 정하지 않았거나 이사회가 대표이사직만 해임한 경우는 아니다)"],["해임·결원·직무대행자 · 결원","임기 만료·사임으로 퇴임한 이사는 새 이사가 취임할 때까지 권리의무가 있다"],["해임·결원·직무대행자 · 가처분","직무집행정지·직무대행자 선임 가처분은 당사자의 신청으로만 하되 급박하면 본안 전에도 할 수 있다"],["해임·결원·직무대행자 · 직무대행자","가처분명령에 다른 정함이 있거나 법원 허가를 얻은 경우 외에는 상무만 할 수 있으나 위반해도 회사는 선의의 제3자에게 책임진다"],["집중투표 · 청구","2인 이상의 이사를 선임하는 총회에서 의결권 없는 주식을 뺀 3% 이상 주주는 정관으로 배제하지 않았으면 총회일 7일 전까지 서면·전자문서로 집중투표를 청구할 수 있다"],["집중투표 · 방식","각 주주는 1주마다 선임할 이사 수만큼 의결권을 가지고 최다 득표자부터 선임되며, 청구 서면은 총회 종결 때까지 본점에 비치한다"],["집중투표 · 대규모 상장회사","자산총액 2조원 이상 상장회사는 1% 이상 주주가 총회일 6주 전까지 청구할 수 있고 2025.9.9 개정으로 정관으로 집중투표를 배제할 수 없다"]]},{"t":"table","title":"이사회 소집·결의 · 이사회 권한·위원회·의사록","head":["구분","내용"],"rows":[["이사회 소집·결의 · 소집","이사회는 각 이사가 소집하되 이사회 결의로 소집권자를 정할 수 있고, 소집권자가 정당한 이유 없이 거절하면 다른 이사가 직접 소집한다"],["이사회 소집·결의 · 통지","회일 1주간 전에 각 이사와 감사에게 통지하되 정관으로 단축할 수 있고 이사·감사 전원이 동의하면 절차 없이 열 수 있다"],["이사회 소집·결의 · 결의","이사 과반수 출석과 출석이사 과반수로 하고 정관으로 높일 수만 있다"],["이사회 소집·결의 · 참가","음성을 동시에 송수신하는 원격통신 참가가 허용되며 대리 출석과 특별이해관계 이사의 의결권 행사는 허용되지 않는다"],["이사회 권한·위원회·의사록 · 이사회 결정","지배인 선임·해임, 지점 설치·이전·폐지 등 업무집행은 이사회가 정한다"],["이사회 권한·위원회·의사록 · 정관으로 총회 권한","대표이사 선정·신주발행·준비금 자본전입·전환사채 발행은 정관으로 주주총회 권한으로 할 수 있다"],["이사회 권한·위원회·의사록 · 위원회","2인 이상의 이사(감사위원회는 3명 이상)로 구성하고, 총회 승인사항의 제안, 대표이사 선임·해임, 위원회 설치·위원 선임은 위임하지 못하며 이사회는 감사위원회 외 위원회의 결의를 다시 결의할 수 있다"],["이사회 권한·위원회·의사록 · 의사록","이사회의사록 열람·등사는 주주 단독으로 청구하고 회사가 거절하면 법원 허가를 얻어 열람한다"]]},{"t":"table","title":"대표이사 · 충실의무·경업·사업기회·자기거래","head":["구분","내용"],"rows":[["대표이사 · 선정","대표이사는 이사회가 선정하고 정관으로 주주총회에서 선정하게 할 수 있으며 영업에 관한 재판상·재판외의 모든 행위를 한다"],["대표이사 · 공동대표","공동대표이사에 대한 제3자의 의사표시는 1인에게 하면 효력이 있다"],["대표이사 · 표현대표이사","사장·전무 등 명칭을 쓴 표현대표이사의 행위는 선의·무중과실 제3자에게 회사가 책임진다"],["대표이사 · 이사회 결의 없는 거래","이사회 결의가 필요한 거래를 결의 없이 하면 상대방이 이를 알았거나 중대한 과실로 몰랐을 때만 무효이다(2021 전원합의체)"],["대표이사 · 소송","회사와 이사 사이의 소송은 감사가 회사를 대표한다"],["충실의무·경업·사업기회·자기거래 · 충실의무","2025.7.22 개정 제382조의3은 이사가 회사 및 주주를 위하여 직무를 충실히 수행하고 총주주의 이익을 보호하며 전체 주주의 이익을 공평하게 대우하도록 정한다"],["충실의무·경업·사업기회·자기거래 · 경업·겸직","이사회 승인(일반 결의)이 필요하고 위반 거래가 자기 계산이면 회사의 계산으로 볼 수 있다"],["충실의무·경업·사업기회·자기거래 · 사업기회·자기거래","사업기회 이용과 이사·주요주주 및 그 배우자·직계존비속 등의 자기거래는 이사 3분의 2 이상의 승인이 필요하다"],["충실의무·경업·사업기회·자기거래 · 추정","사업기회 유용으로 얻은 이익은 회사의 손해로 추정한다"]]},{"t":"table","title":"이사의 책임 · 집행임원·상장회사 특례","head":["구분","내용"],"rows":[["이사의 책임 · 회사에 대한 책임","고의·과실로 법령·정관에 위반하거나 임무를 게을리한 이사는 회사에 연대하여 배상하고, 이사회 결의에 참가해 의사록에 이의를 적지 않은 이사는 찬성한 것으로 추정한다"],["이사의 책임 · 면제","회사에 대한 책임은 총주주의 동의로 면제하고, 정관으로 최근 1년 보수의 6배(사외이사·독립이사 3배)를 넘는 금액을 면제할 수 있다"],["이사의 책임 · 면제 제외","고의·중과실, 경업, 사업기회 유용, 자기거래에는 적용하지 않는다"],["이사의 책임 · 제3자에 대한 책임","고의·중과실이 있을 때 지고, 업무집행지시자·명예회장 등은 이사로 보아 연대책임을 진다"],["집행임원·상장회사 특례 · 집행임원 설치회사","대표이사를 두지 못하고 이사회가 집행임원과 대표집행임원을 선임하고, 집행임원 임기는 정관에 다른 규정이 없으면 2년을 넘지 못하며 3개월에 1회 이상 이사회에 보고한다"],["집행임원·상장회사 특례 · 소집","집행임원은 이사가 이사회 소집 청구에 응하지 않으면 법원 허가를 받아 소집하지만 감사는 허가 없이 소집한다"],["집행임원·상장회사 특례 · 독립이사","상장회사는 이사 총수의 3분의 1 이상을 독립이사로 하고 자산총액 2조원 이상이면 3명 이상·이사 총수의 과반수로 한다"],["집행임원·상장회사 특례 · 준법지원인","자산총액 5천억원 이상 상장회사는 준법통제기준과 준법지원인(임기 3년)을 둔다"]]}],"9":[{"t":"table","title":"감사의 선임·임기 등","head":["구분","내용"],"rows":[["감사의 선임·임기 · 선임","감사는 주주총회에서 선임하고, 의결권 없는 주식을 뺀 발행주식총수의 3%(정관으로 더 낮출 수 있음)를 넘는 주식은 그 초과분만 의결권을 행사하지 못한다"],["감사의 선임·임기 · 전자투표·소규모","전자투표를 도입한 회사는 출석 의결권의 과반수만으로 감사를 선임할 수 있고, 자본금 10억원 미만 회사는 감사를 두지 않을 수 있다"],["감사의 선임·임기 · 임기","취임 후 3년 내 최종 결산기에 관한 정기총회 종결 때까지"],["감사의 선임·임기 · 해임","정당한 이유 없이 임기 중 해임되면 손해배상을 청구하며 총회에서 해임에 관한 의견을 진술할 수 있다"],["감사의 겸직 금지·권한 · 겸직 금지","감사는 회사 및 자회사의 이사·지배인 기타 사용인의 직무를 겸하지 못하지만 자회사의 감사는 겸할 수 있고, 모회사 이사가 자회사 감사를 겸하는 것도 막지 않는다"],["감사의 겸직 금지·권한 · 조사","언제든지 이사에게 영업 보고를 요구하고 업무·재산상태를 조사하고, 모회사 감사는 필요하면 자회사에 영업 보고를 요구한다"],["감사의 겸직 금지·권한 · 이사회","이사회에 출석해 의견을 진술하되 의결권은 없고, 이사회 소집을 청구했는데 응하지 않으면 법원 허가 없이 직접 소집한다"],["감사의 겸직 금지·권한 · 청구","이사에 대한 유지청구와 임시총회 소집청구도 할 수 있다"],["감사의 책임 · 손해배상","감사가 임무를 게을리하면 회사에 손해를 배상하고 이사도 책임이 있으면 연대한다"],["감사의 책임 · 면제","정관에 따른 보수 6배 초과 면제는 고의·중과실이면 적용되지 않는다"],["감사의 책임 · 책임 해제","재무제표 승인 후 2년 내에 다른 결의가 없으면 책임을 해제한 것으로 보지만 부정행위로 인한 책임은 해제되지 않는다"]]},{"t":"table","title":"감사위원회 · 대규모 상장회사의 감사위원회","head":["구분","내용"],"rows":[["감사위원회 · 설치","정관에 따라 감사에 갈음하여 설치하고 설치하면 감사를 둘 수 없다"],["감사위원회 · 구성","3명 이상의 이사로 구성하되 사외이사가 3분의 2 이상이어야 한다"],["감사위원회 · 대표·해임","대표는 위원회가 스스로 결의로 정하고, 이사회가 위원을 해임하려면 이사 총수의 3분의 2 이상의 결의가 필요하며 해임되어도 이사직은 남는다"],["감사위원회 · 재결의","이사회는 감사위원회의 결의를 다시 결의하지 못한다"],["대규모 상장회사의 감사위원회 · 설치","자산총액 2조원 이상 상장회사는 감사위원회를 두어야 하고 위원의 선임·해임은 주주총회 권한이며 정관으로도 이사회에 넘기지 못한다"],["대규모 상장회사의 감사위원회 · 분리 선임","2025.9.9 개정으로 위원 중 2명(정관으로 3명 이상 가능)은 다른 이사와 분리하여 선임한다"],["대규모 상장회사의 감사위원회 · 의결권 제한","위원 선임·해임 때 발행주식총수의 3%를 넘는 주식은 의결권이 제한되며 최대주주는 특수관계인 등을 합산한다"],["대규모 상장회사의 감사위원회 · 대표·보고서","감사위원회의 대표는 독립이사여야 하고, 감사보고서는 총회일 1주 전까지 제출할 수 있다"]]},{"t":"table","title":"소수주주권 보유비율(비상장) · 상장회사 소수주주권","head":["구분","내용"],"rows":[["소수주주권 보유비율(비상장) · 1% 이상","이사의 위법행위 유지청구, 대표소송·다중대표소송(모회사 주식 기준), 총회 검사인 선임 청구"],["소수주주권 보유비율(비상장) · 3% 이상","임시총회 소집청구, 주주제안, 집중투표 청구, 이사·감사·청산인 해임청구, 회계장부 열람, 업무·재산 검사인 선임 청구"],["소수주주권 보유비율(비상장) · 10% 이상","해산판결 청구이고, 주주제안과 집중투표만 의결권 없는 주식을 뺀 발행주식총수가 기준이다"],["상장회사 소수주주권 · 임시총회 소집","1천분의 15"],["상장회사 소수주주권 · 주주제안","1천분의 10"],["상장회사 소수주주권 · 이사·감사 해임","1만분의 50"],["상장회사 소수주주권 · 회계장부 열람","1만분의 10"],["상장회사 소수주주권 · 유지청구","10만분의 50"],["상장회사 소수주주권 · 대표소송","1만분의 1"],["상장회사 소수주주권 · 다중대표소송","1만분의 50"]]},{"t":"table","title":"회계장부 열람·이사회의사록 · 대표소송","head":["구분","내용"],"rows":[["회계장부 열람·이사회의사록 · 회계장부","3% 이상 주주는 이유를 붙인 서면으로 회계장부 열람·등사를 청구하고, 회사는 청구가 부당함을 증명하지 못하면 거부하지 못한다"],["회계장부 열람·이사회의사록 · 서류","재무제표·영업보고서·감사보고서와 정관·총회의사록·주주명부는 주주와 채권자가 영업시간 내에 열람할 수 있다"],["회계장부 열람·이사회의사록 · 이사회의사록","주주가 지분 요건 없이 청구한다"],["대표소송","1% 이상 주주가 이유를 적은 서면으로 회사에 소 제기를 청구 → 회사가 30일 내에 제기하지 않으면(회복할 수 없는 손해 염려가 있으면 즉시) 본점소재지 지방법원에 대표소송 제기 → 제소 후 1% 미만이 되어도 효력이 유지되나 주식을 전혀 갖지 않게 되면 원고적격을 잃는다 → 취하·포기·인락·화해는 법원 허가가 필요하고 회사는 허가 없이 참가할 수 있다 → 승소 주주는 소송비용 외 상당한 비용을 회사에 청구하고 패소 주주는 악의가 있을 때만 배상한다 → 다중대표소송은 모회사 1% 주주가 자회사 이사에 대하여 같은 방식으로 제기하고 자회사도 참가할 수 있다"]]}],"10":[{"t":"table","title":"신주인수권과 제3자 배정 등","head":["구분","내용"],"rows":[["신주인수권과 제3자 배정 · 권리","주주는 법률상 당연히 가진 주식 수에 따라 신주의 배정을 받을 권리가 있다(제418조 제1항)"],["신주인수권과 제3자 배정 · 제3자 배정","주주 외의 자에게 배정하려면 정관에 근거가 있고 신기술 도입·재무구조 개선 등 경영상 목적을 달성하는 데 필요해야 한다"],["신주인수권과 제3자 배정 · 배정기준일","2주간 전에 공고하고, 신주인수권자에게 청약하지 않으면 권리를 잃는다는 뜻을 통지한다"],["신주인수권증서 · 양도","정관이나 이사회 결의로 신주인수권을 양도할 수 있음을 정한 경우 양도는 신주인수권증서의 교부로만 하고 점유자는 적법한 소지인으로 추정된다"],["신주인수권증서 · 청약","증서를 발행하면 증서로 청약하되 증서를 잃은 자는 주식청약서로 청약할 수 있다"],["신주인수권증서 · 전자등록","정관에 따라 증서 대신 전자등록부에 신주인수권을 등록할 수 있다"],["납입·주주가 되는 시기 · 납입","이사는 인수인에게 납입기일에 인수가액 전액을 납입시키고, 인수인은 회사의 동의 없이 납입채무와 회사에 대한 채권을 상계하지 못한다"],["납입·주주가 되는 시기 · 실권","납입기일까지 납입하지 않은 인수인은 최고 없이 당연히 권리를 잃고, 납입한 인수인은 납입기일의 다음 날부터 주주가 된다"],["납입·주주가 되는 시기 · 미인수","변경등기 후 인수되지 않은 주식이나 청약이 취소된 주식은 이사가 공동으로 인수한 것으로 본다"],["납입·주주가 되는 시기 · 무효 주장 제한","변경등기일부터 1년이 지나면 인수인은 청약서 요건 흠결을 이유로 무효를 주장하지 못한다"]]},{"t":"table","title":"액면미달 발행·불공정 인수 · 유지청구·신주발행무효","head":["구분","내용"],"rows":[["액면미달 발행·불공정 인수 · 요건","회사 성립 후 2년이 지난 뒤 주주총회 특별결의(최저발행가액 결정)와 법원 인가를 얻어 한다"],["액면미달 발행·불공정 인수 · 발행 기간","인가일부터 1월 내에 발행하되 법원은 이 기간을 연장할 수 있으며 채권자 이의절차는 없다"],["액면미달 발행·불공정 인수 · 미상각액","변경등기에 적는다"],["액면미달 발행·불공정 인수 · 불공정 인수","이사와 통모하여 현저하게 불공정한 가액으로 인수한 자는 회사에 공정가액과의 차액을 지급할 의무가 있다"],["유지청구·신주발행무효 · 유지청구","법령·정관에 위반하거나 현저하게 불공정한 방법으로 신주를 발행해 불이익을 받을 염려가 있는 주주는 회사에 발행 유지를 청구할 수 있다"],["유지청구·신주발행무효 · 무효의 소","주주·이사·감사가 신주 발행일부터 6월 내에 소로만 주장한다"],["유지청구·신주발행무효 · 판결","판결이 확정되면 신주는 장래에 대하여 효력을 잃으며 회사는 납입금을 반환한다"]]},{"t":"table","title":"자본금 감소 · 감자무효의 소","head":["구분","내용"],"rows":[["자본금 감소 · 결의","자본금 감소는 주주총회 특별결의로 하고 감소 방법을 정한다"],["자본금 감소 · 결손 보전","결손 보전을 위한 감소는 보통결의로 하고 채권자보호절차도 필요 없다"],["자본금 감소 · 사채권자","사채권자가 이의하려면 사채권자집회의 결의가 있어야 하고 법원은 사채권자를 위해 이의기간을 연장할 수 있다"],["자본금 감소 · 주식병합","1월 이상의 주권제출기간을 공고·통지하고 그 기간이 끝난 때 효력이 생기며 채권자보호절차가 끝나지 않았으면 끝난 때 생긴다"],["감자무효의 소 · 제소권자·기간","주주·이사·감사·청산인·파산관재인과 감자를 승인하지 않은 채권자가 변경등기일부터 6개월 내에 회사를 피고로 소로만 주장한다"],["감자무효의 소 · 판결","대세효와 소급효가 있어 설립·합병·분할·신주발행 무효판결과 달리 확정 전의 법률관계에도 미친다"],["감자무효의 소 · 등기","판결이 확정되면 본점 소재지에서 등기한다"]]},{"t":"table","title":"사채 발행·사채관리회사·사채권자집회 · 전환사채·신주인수권부사채","head":["구분","내용"],"rows":[["사채 발행·사채관리회사·사채권자집회 · 발행","사채는 이사회 결의로 발행하고 총액을 계약으로 인수하면 사채청약서가 필요 없으며 모집이 끝나면 이사가 전액 또는 제1회 납입을 시키고 채권은 전액 납입 후 발행한다"],["사채 발행·사채관리회사·사채권자집회 · 기명사채","이전은 사채원부 기재와 채권에 성명 기재가 있어야 회사·제3자에 대항하고 상환청구권 시효는 10년이다"],["사채 발행·사채관리회사·사채권자집회 · 사채관리회사","사채의 인수인은 사채관리회사가 될 수 없고 사채관리회사는 발행회사와 사채권자집회의 동의나 부득이한 사유에 따른 법원 허가로 사임한다"],["사채 발행·사채관리회사·사채권자집회 · 사채권자집회","결의는 출석 의결권 3분의 2 이상과 사채 총액 3분의 1 이상으로 하고 법원 인가를 받아야 효력이 생기되 그 종류 사채권자 전원이 동의한 결의는 인가 없이 효력이 있다"],["전환사채·신주인수권부사채 · 제3자 발행","주주 외의 자에게 발행하면 정관에 규정이 없을 때 주주총회 특별결의로 정하고 경영상 목적이 필요하다"],["전환사채·신주인수권부사채 · 양도","전환권은 사채와 분리하여 양도할 수 없고, 신주인수권증권이 발행되면 신주인수권은 증권의 교부로만 양도하며 선의취득이 인정된다"],["전환사채·신주인수권부사채 · 행사","신주인수권 행사로 발행할 주식의 발행가액 합계는 각 사채 금액을 넘지 못하고, 전액을 납입한 때 주주가 되며 대용납입이 아니면 사채는 남는다"]]}],"11":[{"t":"table","title":"자본금 등","head":["구분","내용"],"rows":[["자본금 · 액면주식 회사","자본금은 발행주식의 액면총액이다"],["자본금 · 무액면주식 회사","발행가액의 2분의 1 이상으로서 이사회(주주총회가 신주발행을 정하는 회사는 주주총회)가 자본금으로 계상하기로 한 금액의 총액이다"],["자본금 · 계상하지 않은 금액","자본준비금으로 적립한다"],["자본금 · 전환·등기","액면·무액면 사이의 전환으로 자본금은 바뀌지 않고, 자본금의 액은 설립등기사항이다"],["재무제표·영업보고서·감사보고서 · 작성","이사는 매 결산기 재무제표와 영업보고서를 작성해 이사회 승인을 받고, 감사는 서류를 받은 날부터 4주 내에 감사보고서를 이사에게 제출한다"],["재무제표·영업보고서·감사보고서 · 비치·열람","이사는 정기총회 1주간 전부터 서류를 본점에 5년, 등본을 지점에 3년 비치하고, 주주와 회사채권자는 영업시간 내에 언제든지 열람할 수 있다"],["재무제표·영업보고서·감사보고서 · 정기총회","재무제표를 승인하고 영업보고서는 보고만 받는다"],["이사회의 재무제표 승인 특칙 · 요건","정관으로 정하면 외부감사인의 적정의견과 감사(감사위원) 전원의 동의를 요건으로 이사회 결의로 재무제표를 승인할 수 있고, 이때 이사는 그 내용을 주주총회에 보고한다"],["이사회의 재무제표 승인 특칙 · 이익배당","이 경우 이익배당도 이사회 결의로 정한다"],["이사회의 재무제표 승인 특칙 · 책임 해제","재무제표 승인 후 2년 내에 다른 결의가 없으면 이사·감사의 책임을 해제한 것으로 보되 부정행위는 해제되지 않는다"]]},{"t":"table","title":"법정준비금 · 준비금의 자본금 전입","head":["구분","내용"],"rows":[["법정준비금 · 이익준비금","회사는 자본금의 2분의 1이 될 때까지 매 결산기 이익배당액의 10분의 1 이상을 이익준비금으로 적립하고, 주식배당은 적립 대상에서 제외된다"],["법정준비금 · 결손 보전","자본준비금과 이익준비금은 어느 것이든 결손 보전에 충당할 수 있다"],["법정준비금 · 합병","합병으로 소멸하는 회사의 법정준비금은 존속·신설회사가 승계할 수 있다"],["법정준비금 · 감액","준비금 총액이 자본금의 1.5배를 넘으면 주주총회 결의로 초과액 범위에서 감액할 수 있다"],["준비금의 자본금 전입 · 결정","준비금의 자본금 전입은 이사회가 정하고 정관으로 주주총회 결의사항으로 할 수 있다"],["준비금의 자본금 전입 · 신주","주주에게 주식 수에 따라 신주를 발행한다"],["준비금의 자본금 전입 · 주주가 되는 시기","이사회 결의면 이사회가 정한 신주배정기준일에, 주주총회 결의면 결의한 때 주주가 된다"]]},{"t":"table","title":"배당가능이익과 위법배당 · 주식배당","head":["구분","내용"],"rows":[["배당가능이익과 위법배당 · 한도","이익배당은 대차대조표의 순자산액에서 자본금, 적립된 자본·이익준비금, 그 결산기에 적립할 이익준비금, 미실현이익을 뺀 금액을 한도로 하며 임의준비금은 빼지 않는다"],["배당가능이익과 위법배당 · 위법배당","한도를 넘은 배당에 대하여 회사채권자는 배당한 이익을 회사에 반환하라고 청구할 수 있다"],["배당가능이익과 위법배당 · 지급","배당은 종류주식이 아니면 주식 수에 따르고 결의일부터 1개월 내에 지급하며 지급청구권은 5년의 시효로 소멸한다"],["주식배당 · 한도","주주총회 결의로 이익배당을 새로 발행하는 주식으로 할 수 있으나 이익배당총액의 2분의 1을 넘지 못한다"],["주식배당 · 발행가","주식의 권면액으로 하고 종류주식 회사는 같은 종류의 주식으로 할 수 있으며, 액면총액만큼 자본금이 늘어난다"],["주식배당 · 주주가 되는 시기","주식배당을 받은 주주는 결의한 총회가 종결한 때부터 신주의 주주가 되고 등록질권자의 권리는 새 주식에 미친다"]]},{"t":"table","title":"현물배당 · 중간배당","head":["구분","내용"],"rows":[["현물배당 · 근거","정관에 근거가 있으면 금전 외의 재산으로 배당할 수 있고, 일반 이익배당처럼 주주총회 보통결의(재무제표를 이사회가 승인하는 회사는 이사회 결의)로 정한다"],["현물배당 · 금전 청구","주주가 현물 대신 금전 지급을 청구할 수 있게 하면 그 금액과 청구기간을 정하고, 일정 수 미만 주식을 가진 주주에게 금전을 지급하도록 정할 수도 있다"],["중간배당 · 요건","연 1회의 결산기를 정한 회사만 정관으로 정하여 영업연도 중 1회에 한해 이사회 결의로 일정한 날의 주주에게 중간배당을 할 수 있다"],["중간배당 · 현물","중간배당도 현물로 할 수 있다"],["중간배당 · 결의 기관","중간배당은 주주총회가 아니라 이사회 결의사항이다"]]}],"12":[{"t":"table","title":"합병 일반 등","head":["구분","내용"],"rows":[["합병 일반 · 종류","회사는 종류가 달라도 합병할 수 있으나 한쪽이 주식회사·유한회사·유한책임회사이면 존속·신설회사도 그중 하나여야 하고, 해산 후의 회사는 존립 중의 회사를 존속회사로 하는 경우에만 합병한다"],["합병 일반 · 합명·합자","존속회사가 주식회사이고 상대가 합명·합자회사면 그 총사원의 동의로 합병계약서를 작성한다"],["합병 일반 · 법원 인가","합병 후 회사가 주식회사인 주식회사·유한회사 합병은 법원 인가를 받아야 효력이 있다"],["합병 일반 · 설립위원","신설합병의 정관 작성 등 설립행위는 각 회사가 선임한 설립위원이 공동으로 한다"],["합병 절차와 대가","합병계약서는 주주총회 특별결의로 승인하고, 계약서에 정관변경을 적어 승인하면 따로 정관변경 결의가 필요 없다 → 합병대가는 전부를 금전이나 그 밖의 재산으로 줄 수 있고, 존속회사는 대가로 줄 모회사 주식을 취득할 수 있다(삼각합병) → 결의일부터 2주 내에 1월 이상의 기간을 정해 채권자 이의를 공고·최고 → 합병 등기는 본점 소재지에서 2주 내에 한다"],["간이합병·소규모합병 · 간이합병","소멸회사의 총주주가 동의하거나 존속회사가 소멸회사 발행주식총수의 90% 이상을 가진 때 소멸회사 총회 승인을 이사회 승인으로 갈음 · 소멸회사 반대주주는 매수청구를 할 수 있다"],["간이합병·소규모합병 · 소규모합병","존속회사가 발행하는 신주가 발행주식총수의 10% 이하이고 금전 등 대가가 존속회사 순자산의 5% 이하인 때 존속회사 총회 승인을 이사회 승인으로 갈음 · 존속회사 주주는 매수청구를 할 수 없고 20% 이상 주주가 반대하면 할 수 없다"],["간이합병·소규모합병 · 공통","두 경우 모두 채권자보호절차는 거친다"]]},{"t":"table","title":"합병무효의 소 · 회사분할","head":["구분","내용"],"rows":[["합병무효의 소 · 제소","각 회사의 주주·이사·감사·청산인·파산관재인 또는 합병을 승인하지 않은 채권자가 합병등기일부터 6월 내에 소로만 주장한다"],["합병무효의 소 · 원인","현저히 불공정한 합병비율도 무효 원인이 될 수 있다"],["합병무효의 소 · 판결","판결은 소급효가 없어 확정 전의 법률관계에 영향을 주지 않는다"],["회사분할 · 승인","분할·분할합병은 주주총회 특별결의로 승인하고 이 결의에서는 의결권이 배제되는 주주도 의결권이 있고, 주주의 부담이 가중되면 그 주주 전원의 동의가 필요하다"],["회사분할 · 해산 후 회사","존립 중의 회사를 존속회사로 하거나 새로 회사를 설립하는 경우에만 분할할 수 있다"],["회사분할 · 신설회사","분할계획서에 따라 권리의무를 승계하고, 분할회사의 출자만으로 설립되면 검사인 조사가 필요 없으며 분할회사의 자기주식에는 신주를 배정하지 못한다"]]},{"t":"table","title":"분할 채무 책임 · 주식의 포괄적 교환","head":["구분","내용"],"rows":[["분할 채무 책임 · 원칙","분할 후 회사들은 분할 전 채무에 대하여 연대책임을 지는 것이 원칙이다"],["분할 채무 책임 · 예외","주주총회 특별결의로 신설·승계회사가 분할계획서나 분할합병계약서에 승계하기로 정한 채무만 책임지도록 정할 수 있고, 이때 채권자보호절차를 거친다"],["분할 채무 책임 · 분할합병","분할회사와 분할승계회사가 각각 채권자보호절차를 거친다"],["주식의 포괄적 교환 · 절차","주식교환계약서를 주주총회 특별결의로 승인하고 채권자보호절차는 없고, 계약서에 정한 교환일에 완전자회사 주식이 완전모회사로 이전한다"],["주식의 포괄적 교환 · 간이·소규모","완전자회사 총주주 동의나 완전모회사의 90% 이상 보유 시 간이교환, 완전모회사가 발행하는 신주가 10% 이하이고 교환대가가 순자산의 5% 이하이면 소규모교환이 되며 소규모교환은 계약서 작성일부터 2주 내에 공고·통지하고 20% 이상 반대 시 할 수 없다"],["주식의 포괄적 교환 · 매수청구권","반대주주 매수청구권은 일반 교환과 간이교환에 있고 소규모교환에는 없다"],["주식의 포괄적 교환 · 무효의 소","교환무효의 소는 교환일부터 6월 내에 제기하고 판결은 장래효만 있다"]]},{"t":"table","title":"주식의 포괄적 이전 · 조직변경","head":["구분","내용"],"rows":[["주식의 포괄적 이전 · 효력","주식이전은 완전모회사가 본점소재지에서 설립등기를 함으로써 효력이 생기고, 간이·소규모 이전 제도는 없다"],["주식의 포괄적 이전 · 자본금","완전모회사의 자본금은 완전자회사의 순자산액에서 주주에게 줄 금전 등을 뺀 금액을 넘지 못하고, 주식이전으로 모회사 주식을 취득한 자회사는 6월 내에 처분한다"],["주식의 포괄적 이전 · 무효판결","무효판결이 확정되면 완전모회사는 발행한 주식의 주주에게 완전자회사 주식을 돌려준다"],["조직변경 · 범위","조직변경은 합명↔합자, 주식↔유한회사, 주식↔유한책임회사 사이에서만 인정된다"],["조직변경 · 합명·합자","합명→합자는 총사원의 동의, 유한책임사원이 모두 퇴사한 합자회사의 합명회사 변경은 무한책임사원 전원의 동의"],["조직변경 · 주식회사→유한","주식회사→유한회사·유한책임회사는 총주주의 동의가 필요하고 사채 상환을 끝내지 않은 주식회사는 유한회사가 되지 못한다"],["조직변경 · 유한회사→주식회사","총사원 일치(정관으로 총사원 반수 이상·의결권 4분의 3 이상 가능)와 법원 인가가 필요하고, 발행 주식의 발행가액 총액은 현존 순재산액을 넘지 못한다"]]}],"13":[{"t":"table","title":"주식회사의 해산사유 · 해산판결·회사 계속","head":["구분","내용"],"rows":[["주식회사의 해산사유 · 해산사유(제517조)","존립기간 만료 등 정관에 정한 사유, 합병, 분할·분할합병, 파산, 법원의 해산명령·해산판결, 주주총회 특별결의"],["주식회사의 해산사유 · 해산사유가 아닌 것","주주가 1인이 되는 것은 해산사유가 아니다"],["주식회사의 해산사유 · 통지","해산하면 파산의 경우 외에는 이사가 지체 없이 주주에게 통지한다"],["해산판결·회사 계속 · 해산판결","업무가 현저한 정돈상태로 회복할 수 없는 손해가 생기거나 회사재산 관리·처분의 현저한 실당으로 존립이 위태로울 때 부득이한 사유가 있으면 발행주식총수의 10% 이상 주주가 법원에 해산을 청구할 수 있다"],["해산판결·회사 계속 · 회사 계속","존립기간 만료 등 정관 사유나 총회 결의로 해산한 회사는 특별결의로 계속할 수 있다"]]},{"t":"table","title":"휴면회사 · 합명·합자회사의 해산과 계속","head":["구분","내용"],"rows":[["휴면회사","최후 등기 후 5년이 지난 회사 → 법원행정처장의 관보 공고일부터 2월 내에 영업을 폐지하지 않았다는 신고를 하지 않으면 신고기간 만료 때 해산한 것으로 본다 → 그 후 3년 내에는 특별결의로 계속할 수 있다 → 계속하지 않으면 3년이 지난 때 청산이 종결된 것으로 본다"],["합명·합자회사의 해산과 계속 · 합명회사","존립기간 만료 등 정관 사유, 총사원의 동의, 사원이 1인으로 된 때, 합병, 파산, 법원의 명령·판결로 해산하고, 사원 1인이 되면 새 사원을 가입시켜 계속할 수 있다"],["합명·합자회사의 해산과 계속 · 합자회사","무한책임사원 또는 유한책임사원 전원이 퇴사하면 해산하고, 남은 사원 전원의 동의로 빠진 쪽 사원을 새로 가입시켜 계속할 수 있다"],["합명·합자회사의 해산과 계속 · 유한회사","사원이 1인이 되어도 해산하지 않는다"]]},{"t":"table","title":"청산인 · 청산 절차","head":["구분","내용"],"rows":[["청산인 · 주식회사","해산하면 합병·분할·파산의 경우 외에는 이사가 청산인이 되고 정관이나 총회로 다른 사람을 정할 수 있으며, 청산인 임기에는 제한이 없다"],["청산인 · 해임","법원이 선임한 경우 외에는 주주총회 보통결의로 언제든지 해임하고, 현저히 부적임하면 3% 이상 주주가 법원에 해임을 청구한다"],["청산인 · 합명회사","총사원 과반수로 청산인을 선임하고(없으면 업무집행사원), 사원 1인이나 해산명령·판결로 해산하면 법원이 청산인을 선임한다"],["청산 절차","청산인은 취임 후 지체 없이 재산목록과 대차대조표를 작성해 주주총회 승인을 받고, 정기총회에 대차대조표와 사무보고서를 제출해 승인을 구한다 → 취임일부터 2월 내에 2월 이상의 신고기간을 정해 채권신고를 2회 이상 공고로 최고 → 알고 있는 채권자는 신고하지 않아도 청산에서 제외하지 못한다 → 청산에서 제외된 채권자는 분배되지 않은 잔여재산에 대해서만 변제를 청구할 수 있다"]]},{"t":"table","title":"청산 종결 · 임의청산(합명·합자)","head":["구분","내용"],"rows":[["청산 종결 · 결산보고","청산사무가 끝나면 청산인은 지체 없이 결산보고서를 작성해 주주총회 승인을 받고, 승인이 있으면 부정행위가 아닌 한 청산인의 책임을 해제한 것으로 본다"],["청산 종결 · 보존","회사 장부와 영업·청산에 관한 중요서류는 청산종결 등기 후 10년(전표류 5년) 보존한다"],["청산 종결 · 존속","해산한 회사도 청산의 목적 범위 안에서는 존속한다"],["임의청산(합명·합자) · 방법","합명회사는 정관이나 총사원의 동의로 재산처분방법을 정해 임의청산할 수 있고, 이때 해산사유가 있은 날부터 2주간 내에 재산목록과 대차대조표를 작성한다"],["임의청산(합명·합자) · 제한","사원이 1인으로 되거나 법원의 명령·판결로 해산한 경우에는 임의청산을 하지 못하고, 임의청산도 청산이므로 청산을 거치지 않고 바로 소멸하지 않는다"],["임의청산(합명·합자) · 계산서","청산인은 임무가 끝나면 계산서를 작성해 각 사원의 승인을 받는다"]]}],"14":[{"t":"table","title":"합명회사의 설립·사원 책임 등","head":["구분","내용"],"rows":[["합명회사의 설립·사원 책임 · 설립","2인 이상의 사원이 정관을 작성하고 총사원이 기명날인·서명하며, 정관에는 모든 사원의 성명·주민등록번호·주소와 출자의 목적·가격을 적는다"],["합명회사의 설립·사원 책임 · 책임","회사 재산으로 채무를 완제할 수 없으면 각 사원이 연대하여 변제하고, 사원은 회사가 가진 항변으로 채권자에게 대항할 수 있다"],["합명회사의 설립·사원 책임 · 가입 사원","성립 후 가입한 사원도 가입 전 채무에 같은 책임을 진다"],["합명회사의 설립·사원 책임 · 소","설립무효는 사원만 성립일부터 2년 내에 소로만 주장하며 사해설립취소는 채권자가 사원과 회사를 상대로 제기한다"],["합명회사의 업무집행·지분 · 업무집행","정관에 정함이 없으면 각 사원이 업무를 집행하고 대표하며, 업무집행사원은 정관으로 정하고 다른 업무집행사원의 이의가 있으면 행위를 중지하고 과반수 결의에 따른다"],["합명회사의 업무집행·지분 · 지배인","지배인 선임·해임은 업무집행사원이 있어도 총사원 과반수로 한다"],["합명회사의 업무집행·지분 · 정관변경·지분","정관변경과 지분 전부·일부 양도는 총사원(다른 사원 전원)의 동의가 필요하다"],["합명회사의 업무집행·지분 · 경업·자기거래","사원의 경업·겸직은 다른 사원의 동의, 자기거래는 다른 사원 과반수의 결의가 있어야 하고 사원은 신용·노무도 출자할 수 있다"],["합자회사의 유한책임사원 · 출자·책임","유한책임사원은 신용·노무를 출자하지 못하고 출자가액에서 이행한 부분을 뺀 금액을 한도로 회사채무를 변제한다"],["합자회사의 유한책임사원 · 업무","업무집행과 대표를 하지 못하지만 경업·겸직 제한은 받지 않는다"],["합자회사의 유한책임사원 · 지분","지분 양도는 무한책임사원 전원의 동의로 하며 사망하면 상속인이 승계하고 성년후견개시로 퇴사하지 않는다"],["합자회사의 유한책임사원 · 오인","자기를 무한책임사원으로 오인시킨 유한책임사원은 오인하고 거래한 자에게 무한책임사원과 같은 책임을 진다"]]},{"t":"table","title":"합자회사의 무한책임사원·책임 변경 · 유한책임회사의 설립·출자·지분","head":["구분","내용"],"rows":[["합자회사의 무한책임사원·책임 변경 · 업무집행","무한책임사원은 정관에 다른 정함이 없으면 각자 업무를 집행하고, 지배인 선임·해임은 업무집행사원이 있어도 무한책임사원 과반수로 하며 청산인도 무한책임사원 과반수로 선임한다"],["합자회사의 무한책임사원·책임 변경 · 유한→무한","유한책임사원이 무한책임사원이 되면 변경 전 채무에도 무한책임을 진다"],["합자회사의 무한책임사원·책임 변경 · 무한→유한","무한책임사원이 유한책임사원이 되면 변경등기 전 채무에 대하여 등기 후 2년 내에는 무한책임을 진다"],["합자회사의 무한책임사원·책임 변경 · 손익","손익은 정관에 정함이 없으면 출자가액에 비례하여 나눈다"],["유한책임회사의 설립·출자·지분 · 설립·출자","사원 1인으로 설립할 수 있고 사원은 금전 기타 재산으로만 출자하며(신용·노무 불가) 설립등기 때까지 출자를 전부 이행한다"],["유한책임회사의 설립·출자·지분 · 책임","사원의 책임은 출자금액을 한도로 한다"],["유한책임회사의 설립·출자·지분 · 지분","지분 양도는 다른 사원의 동의가 필요하며 회사는 자기 지분을 양수하지 못하고 취득하면 그때 소멸한다"],["유한책임회사의 설립·출자·지분 · 가입·퇴사","새 사원은 정관변경 때 가입하되 출자를 이행하지 않았으면 이행한 때 사원이 되고, 퇴사 사원은 지분을 금전으로 환급받는다"]]},{"t":"table","title":"유한책임회사의 업무집행자 · 유한책임회사의 기관·정관변경·조직변경","head":["구분","내용"],"rows":[["유한책임회사의 업무집행자 · 선정","정관으로 사원 또는 사원이 아닌 자를 업무집행자로 정하고 법인도 업무집행자가 될 수 있으며, 둘 이상이면 각자 업무를 집행하고 정관이나 총사원의 동의로 대표 업무집행자를 정할 수 있다"],["유한책임회사의 업무집행자 · 자기거래","업무집행자의 자기거래는 다른 사원 과반수의 결의가 있어야 한다"],["유한책임회사의 업무집행자 · 불법행위","대표 업무집행자의 업무상 불법행위에는 회사가 연대책임을 진다"],["유한책임회사의 업무집행자 · 소 제기 청구","사원은 지분 요건 없이 업무집행자의 책임을 추궁하는 소의 제기를 청구할 수 있다"],["유한책임회사의 기관·정관변경·조직변경 · 내부관계","내부관계에는 정관이나 상법에 다른 규정이 없으면 합명회사 규정을 준용하고 사원총회가 없어 정기총회 소집의무도 없다"],["유한책임회사의 기관·정관변경·조직변경 · 정관변경","정관에 다른 정함이 없으면 총사원의 동의가 필요하고, 자본금은 정관변경으로 감소하되 감소 후 자본금이 순자산액 이상이면 채권자 이의절차가 필요 없다"],["유한책임회사의 기관·정관변경·조직변경 · 조직변경","총사원의 동의로 주식회사로만 조직변경할 수 있다"],["유한책임회사의 기관·정관변경·조직변경 · 설립무효","설립무효의 소는 사원과 업무집행자가 제기한다"]]},{"t":"table","title":"유한회사의 설립·지분 · 유한회사의 기관","head":["구분","내용"],"rows":[["유한회사의 설립·지분 · 설립","모집설립이 없고 정관은 자본금 규모와 관계없이 공증인 인증으로 효력이 생기며 사원의 성명·주민등록번호·주소를 정관에 적는다"],["유한회사의 설립·지분 · 출자","출자 1좌의 금액은 100원 이상으로 균일하게 하고 최저자본금과 사원 수 제한은 없다"],["유한회사의 설립·지분 · 전보책임","납입·현물출자가 덜 된 것이 성립 후 드러나면 성립 당시의 사원·이사·감사가 연대하여 지급한다"],["유한회사의 설립·지분 · 지분","정관으로 제한하지 않으면 자유롭게 양도하고 사원명부 기재가 회사·제3자 대항요건이며, 지시식·무기명식 증권을 발행하지 못하고 질권 설정은 되지만 약식질은 없다"],["유한회사의 기관 · 이사","이사는 1인 이상이고 여럿이면 정관에 다른 정함이 없을 때 업무집행은 이사 과반수 결의로 하며 대표이사는 사원총회가 정한다"],["유한회사의 기관 · 소송","회사와 이사 사이의 소에서는 사원총회가 회사를 대표할 자를 정한다"],["유한회사의 기관 · 사원총회","소집통지는 1주 전에 하고 총사원 동의가 있으면 소집절차 없이 열거나 서면결의를 할 수 있으며, 목적사항에 총사원이 서면으로 동의하면 서면결의가 있는 것으로 본다"],["유한회사의 기관 · 정관변경·소수사원권","정관변경은 총사원 반수 이상이며 의결권 4분의 3 이상으로 하고, 소수사원권(대표소송 등)은 자본금 3% 이상 출자좌수가 기준이며 집중투표 제도는 없다"]]}],"15":[{"t":"table","title":"어음의 성질과 요건 등","head":["구분","내용"],"rows":[["어음의 성질과 요건 · 성질","어음은 설권증권·무인증권·요식증권이고 지시식으로 발행하지 않아도 배서로 양도하는 당연한 지시증권이다"],["어음의 성질과 요건 · 환어음","환어음에는 환어음 문자, 조건 없는 지급위탁, 지급인, 만기, 지급지, 수취인, 발행일과 발행지, 발행인의 기명날인 또는 서명을 적고(제1조) 약속어음에는 지급인이 없다"],["어음의 성질과 요건 · 보충","만기가 없으면 일람출급, 지급지가 없으면 지급인 명칭에 부기한 지, 발행지가 없으면 발행인 명칭에 부기한 지로 보며(제2조) 약속어음은 지급지가 없으면 발행지를 지급지로 본다"],["기명날인·서명과 대리 · 기명","기명은 본명이 아니어도 되고 아호·예명도 쓸 수 있으며 기명과 날인의 명의가 달라도 된다"],["기명날인·서명과 대리 · 무인·법인","무인(지장)은 날인이 아니고 법인은 대표기관이 법인을 위한다는 뜻을 표시하고 기명날인해야 하므로 법인 명칭과 법인 인감만 찍은 어음은 무효다"],["기명날인·서명과 대리 · 무권대리","대리권 없이 대리인으로 기명날인한 자는 어음상 책임을 지고 어음금을 지급하면 본인과 같은 권리를 가지며(제8조) 표현대리가 성립하면 소지인은 본인과 무권대리인 모두에게 청구할 수 있다"],["이자·금액·발행인 담보 · 이자(제5조)","이자 약정은 일람출급과 일람 후 정기출급 어음에만 적을 수 있고 그 밖의 어음에 적은 이자 약정은 적지 않은 것으로 보며 이율이 없으면 이자 약정이 없는 것으로 보고 날짜가 없으면 발행한 날부터 이자를 계산한다"],["이자·금액·발행인 담보 · 금액(제6조)","금액을 글자와 숫자로 적어 차이가 나면 글자로 적은 금액, 같은 방식으로 중복해 적어 차이가 나면 최소금액이 어음금액이다"],["이자·금액·발행인 담보 · 발행인 담보(제9조)","환어음 발행인은 인수와 지급을 담보하고 인수무담보 문구는 유효하지만 지급무담보 문구는 적지 않은 것으로 본다"]]},{"t":"table","title":"백지어음 · 배서의 요건과 효력","head":["구분","내용"],"rows":[["백지어음 · 보충","미완성으로 발행한 어음에 미리 합의한 내용과 다르게 보충되어도 발행인은 악의·중과실 없는 소지인에게 합의 위반으로 대항하지 못한다(제10조)"],["백지어음 · 선의취득","백지어음도 선의취득 대상이고 보충할 때 보충자의 기명날인은 필요 없다"],["백지어음 · 시효중단","시효 완성 전에 어음금 청구의 소를 냈다면 시효기간이 지난 뒤 변론종결 전에 백지를 보충해도 시효중단 효력이 유지된다"],["배서의 요건과 효력 · 요건(제12조)","배서에 붙인 조건은 적지 않은 것으로 보고 일부의 배서는 무효이며 소지인출급 배서는 백지식 배서와 같다"],["배서의 요건과 효력 · 담보(제15조)","배서인은 반대 문구가 없으면 인수와 지급을 담보하고 무담보배서인은 모든 후자에게 책임이 없으나 배서금지배서인은 직접 피배서인에게는 담보책임을 진다"],["배서의 요건과 효력 · 자격수여(제16조)","배서의 연속으로 권리를 증명하면 적법한 소지인으로 추정하고 말소한 배서는 연속에 관하여 배서하지 않은 것으로 보며 절취자가 말소한 경우도 같다"]]},{"t":"table","title":"추심위임배서·입질배서 · 기한후배서","head":["구분","내용"],"rows":[["추심위임배서·입질배서 · 추심위임배서(제18조)","피배서인은 어음상 모든 권리를 행사하지만 대리를 위한 배서만 할 수 있고 어음채무자는 배서인에게 대항할 수 있는 항변으로만 소지인에게 대항한다"],["추심위임배서·입질배서 · 입질배서(제19조)","권리이전적 효력이 없고 피배서인이 한 배서는 대리를 위한 배서의 효력만 있으며 어음채무자는 소지인이 해할 것을 알고 취득한 경우가 아니면 배서인에 대한 인적 항변으로 대항하지 못한다"],["추심위임배서·입질배서 · 질권 선의취득","입질배서의 피배서인도 질권을 선의취득할 수 있다"],["기한후배서 · 효력(제20조)","지급거절증서가 작성된 뒤나 작성기간이 지난 뒤에 한 배서는 지명채권 양도의 효력만 있고 만기 후라도 그 전에 한 배서는 만기 전 배서와 같다"],["기한후배서 · 판단 기준","기한후배서인지는 문면의 일자가 아니라 실제 배서한 날로 정하고 날짜 없는 배서는 작성기간이 지나기 전에 한 것으로 추정한다"],["기한후배서 · 대항요건·항변","기한후배서로 권리가 이전되는 데 통지·승낙 같은 대항요건은 필요 없지만 인적 항변이 절단되지 않고 선의취득도 없다"]]},{"t":"table","title":"선의취득 · 인수와 지급","head":["구분","내용"],"rows":[["선의취득 · 요건(제16조 제2항)","어떤 사유로든 어음 점유를 잃은 자가 있어도 배서의 연속으로 권리를 증명하는 소지인은 악의 또는 중대한 과실로 취득한 경우가 아니면 어음을 반환할 의무가 없다"],["선의취득 · 판례","양도인이 무권리자인 경우뿐 아니라 대리권 흠결이나 하자가 있는 경우도 선의취득으로 치유된다고 보고 의심할 사정이 있는데 조사 없이 양수하면 중과실이다"],["선의취득 · 제외·효과","지시금지어음과 기한후배서 어음은 선의취득이 없고 선의취득으로 인적 항변은 소멸하지만 물적 항변은 남는다"],["인수와 지급 · 인수","어음 앞면에 지급인의 단순한 기명날인만 있어도 인수로 보고(제25조) 일부인수는 할 수 있으며 다른 기재사항을 변경한 인수는 인수거절로 보되 인수인은 그 문구대로 책임을 진다(제26조)"],["인수와 지급 · 인수제시","일람 후 정기출급 어음은 발행일부터 1년 내에 인수제시하며 발행인은 이 기간을 단축·연장하고 배서인은 단축만 할 수 있다(제23조)"],["인수와 지급 · 지급제시","확정일출급 등은 지급할 날 또는 그 이후 2거래일 내에 지급제시하고(제38조)"],["인수와 지급 · 지급","소지인은 일부지급을 거절하지 못하며 만기에 지급하는 지급인은 사기 또는 중대한 과실이 없으면 면책되고 기명날인의 진위까지 조사할 의무는 없다(제40조)"]]}],"16":[{"t":"table","title":"인적 항변의 절단 등","head":["구분","내용"],"rows":[["인적 항변의 절단 · 원칙","어음채무자는 발행인이나 종전 소지인에 대한 인적 관계로 인한 항변으로 소지인에게 대항하지 못하지만 소지인이 채무자를 해할 것을 알고 취득했으면 대항할 수 있다(제17조)"],["인적 항변의 절단 · 악의","판례상 악의는 항변사유를 아는 것으로 부족하고 자기가 취득하면 항변이 절단되어 채무자가 손해를 입는다는 사정까지 알아야 한다"],["인적 항변의 절단 · 절단되지 않는 경우","상속·합병 같은 포괄승계와 기한후배서로 취득한 자에게는 항변이 절단되지 않는다"],["물적 항변과 교부흠결 · 물적 항변","어음요건 흠결, 시효 소멸, 위조, 제한능력 같은 물적 항변은 소지인의 선의·악의와 관계없이 누구에게나 주장할 수 있다"],["물적 항변과 교부흠결 · 교부흠결","발행인으로 기명날인해 외관을 갖춘 어음이 도난 등으로 의사와 관계없이 유통되었더라도 발행인은 선의의 취득자에게 대항하지 못한다"],["물적 항변과 교부흠결 · 불완전어음","백지어음이 아니라 요건이 빠진 불완전어음이라서 무효라는 점은 발행인이 증명한다"],["원인관계와 어음 · 지급을 위하여","기존 채무에 관하여 어음을 주고받으면서 명시적 합의가 없으면 지급을 위하여 발행한 것으로 추정하므로 원인채무는 소멸하지 않는다"],["원인관계와 어음 · 담보를 위하여","담보를 위하여 발행한 경우 채권자는 원인채권과 어음채권 중 어느 것을 먼저 행사해도 된다"],["원인관계와 어음 · 원인관계 소멸","원인관계가 취소·해제되면 직접 상대방에게는 이를 인적 항변으로 주장해 어음금 지급을 거절할 수 있다"]]},{"t":"table","title":"융통어음 · 위조·변조","head":["구분","내용"],"rows":[["융통어음 · 뜻","타인이 그 어음으로 제3자에게서 금융을 얻게 할 목적으로 수수하는 어음이다"],["융통어음 · 발행인의 책임","발행인은 피융통자에게는 어음상 책임을 지지 않지만 그 어음을 취득한 제3자에게는 융통어음이라는 사실을 알았는지와 관계없이 대항하지 못한다"],["위조·변조 · 위조","피위조자는 소지인의 선의·악의와 관계없이 위조의 항변으로 책임을 면하고 판례상 피위조자가 위조를 주장하면 소지인이 기명날인의 진정을 증명해야 한다"],["위조·변조 · 독립성(제7조)","위조된 기명날인이 있어도 다른 기명날인을 한 자의 채무는 영향을 받지 않으므로 위조어음에 배서한 자는 선의·무중과실이라도 배서인으로서 책임을 진다"],["위조·변조 · 변조(제69조)","어음 문구가 변조되면 변조 후에 기명날인하거나 서명한 자는 변조된 문구대로 책임을 지고 변조 전에 기명날인하거나 서명한 자는 원래 문구대로 책임을 진다"]]},{"t":"table","title":"상환청구의 요건과 통지 · 거절증서 작성 면제","head":["구분","내용"],"rows":[["상환청구의 요건과 통지 · 요건(제43조)","만기에 지급이 거절되면 소지인은 배서인·발행인 등에게 상환청구하고 인수의 전부나 일부가 거절되거나 지급인이 파산한 때에는 만기 전에도 할 수 있다"],["상환청구의 요건과 통지 · 거절증서(제44조)","확정일출급 등의 지급거절증서는 지급할 날 이후 2거래일 내에 작성시킨다"],["상환청구의 요건과 통지 · 통지(제45조)","소지인은 거절증서 작성일 이후 4거래일 내에 자기의 배서인과 발행인에게 거절을 통지하며 배서인은 받은 날 이후 2거래일 내에 앞의 배서인에게 통지한다"],["상환청구의 요건과 통지 · 통지 방법·효과","통지는 어음 반환으로도 할 수 있고 통지하지 않아도 상환청구권을 잃지 않으며 과실로 생긴 손해를 어음금액 한도에서 배상한다"],["거절증서 작성 면제 · 면제(제46조)","발행인·배서인·보증인은 무비용상환이나 거절증서 불필요 문구를 적고 기명날인하거나 서명해 거절증서 작성을 면제할 수 있지만 소지인의 법정기간 내 제시·통지 의무는 면제되지 않는다"],["거절증서 작성 면제 · 발행인의 문구","발행인이 적은 문구는 모든 어음채무자에게 효력이 있고 그런데도 소지인이 거절증서를 작성시키면 비용은 소지인이 부담한다"],["거절증서 작성 면제 · 무비용상환","무비용상환 문구가 있으면 지급제시기간이 지난 소지인은 배서인·발행인에 대한 권리를 잃지만 인수인에 대한 권리는 잃지 않는다"]]},{"t":"table","title":"소멸시효 · 이득상환청구권","head":["구분","내용"],"rows":[["소멸시효 · 인수인과 약속어음 발행인(그 보증인 포함)에 대한 청구권","만기일부터 3년(제70조)"],["소멸시효 · 소지인의 배서인·발행인에 대한 청구권","거절증서 날짜(무비용상환이면 만기일)부터 1년"],["소멸시효 · 배서인의 다른 배서인·발행인에 대한 청구권","환수한 날이나 제소된 날부터 6개월"],["소멸시효 · 기산·중단(제71조)","만기가 공휴일이어도 시효는 만기일 다음 날부터 기산하고 시효의 중단은 그 사유가 생긴 자에 대하여만 효력이 있다"],["이득상환청구권 · 요건","어음상 권리가 절차 흠결이나 시효로 소멸하고 원인채권 등 다른 구제수단도 없을 때 소지인은 발행인·인수인·배서인에게 그들이 받은 이익의 한도에서 상환을 청구한다"],["이득상환청구권 · 생기지 않는 경우","권리 소멸 당시 원인채권이 있었다면 그 뒤 원인채권이 소멸해도 이득상환청구권은 생기지 않고 선의취득으로 권리를 잃은 자나 보충되지 않은 백지어음의 소지인에게도 생기지 않는다"],["이득상환청구권 · 성질","지명채권이라서 선의취득 대상이 아니고 약속어음 발행인이 반환할 이득은 원인관계로 받은 대가다"]]}],"17":[{"t":"table","title":"수표의 요건 등","head":["구분","내용"],"rows":[["수표의 요건 · 요건(제1조)","수표에는 수표 문자, 조건 없는 지급위탁, 지급인, 지급지, 발행일과 발행지, 발행인의 기명날인 또는 서명을 적고 수취인과 만기는 요건이 아니다"],["수표의 요건 · 보충(제2조)","지급지가 없으면 지급인 명칭에 부기한 지(여러 개면 맨 앞에 적은 지), 그것도 없으면 발행지에서 지급하고 발행지가 없으면 발행인 명칭에 부기한 지를 발행지로 본다"],["수표의 요건 · 판례","국내수표는 발행지가 없어도 유효하고 발행일란이 비어도 수표면 다른 곳에 일정한 날이 적혀 있으면 그날을 발행일로 본다"],["지급인과 수표계약 · 지급인(제3조)","수표는 발행인이 처분할 수 있는 자금이 있는 은행을 지급인으로 하고 수표계약에 따라 발행해야 하지만 이를 어겨도 수표의 효력에는 영향이 없다"],["지급인과 수표계약 · 발행 형태(제6조)","자기지시수표, 제3자의 계산으로 하는 위탁수표, 발행인 자신을 지급인으로 하는 자기앞수표를 모두 발행할 수 있다"],["지급인과 수표계약 · 자기앞수표","은행이 발행인이고 분실자가 은행에 지급정지를 청구하는 것은 지급위탁의 취소가 아니다"],["수취인 기재 방식 · 방식(제5조)","수표는 기명식·지시식, 지시금지 기명식, 소지인출급식으로 발행할 수 있다"],["수취인 기재 방식 · 소지인출급식","기명식에 「또는 소지인에게」를 적거나 수취인을 적지 않으면 소지인출급식으로 보아 교부만으로 양도한다"],["수취인 기재 방식 · 지시금지 수표","지명채권 양도 방식으로만 양도한다"],["수취인 기재 방식 · 배서(제20조)","소지인출급식 수표에 배서한 자는 상환청구에 관한 책임을 지지만 그 수표가 지시식으로 바뀌지는 않는다"]]},{"t":"table","title":"적지 않은 것으로 보는 기재 · 일람출급과 제시기간","head":["구분","내용"],"rows":[["적지 않은 것으로 보는 기재 · 인수·이자","수표는 인수하지 못하고 인수 문구는 적지 않은 것으로 보며(제4조) 이자 약정도 적지 않은 것으로 본다(제7조)"],["적지 않은 것으로 보는 기재 · 발행인·금액","발행인은 지급을 담보하고 지급무담보 문구는 적지 않은 것으로 보며(제12조) 금액 기재 차이는 어음과 같이 글자 우선, 중복 기재는 최소금액이다(제9조)"],["적지 않은 것으로 보는 기재 · 배서","배서에 붙인 조건은 적지 않은 것으로 보고 일부의 배서는 무효이며 지급인의 배서는 무효, 지급인에게 한 배서는 영수증의 효력만 있다"],["일람출급과 제시기간 · 일람출급","수표는 일람출급이고 이에 반하는 문구는 적지 않은 것으로 보며 기재된 발행일 전에 제시된 선일자수표도 제시된 날에 지급해야 한다(제28조)"],["일람출급과 제시기간 · 제시기간","국내에서 발행하고 지급할 수표는 10일 내에 지급제시하고 이 기간은 수표에 적힌 발행일부터 계산한다(제29조)"],["일람출급과 제시기간 · 휴일","기간 중의 휴일은 기간에 산입하고 말일이 휴일이면 다음 제1거래일까지 늘어나며 선일자수표의 제시기간과 시효도 적힌 발행일을 기준으로 한다"]]},{"t":"table","title":"지급위탁 취소와 지급 · 횡선수표","head":["구분","내용"],"rows":[["지급위탁 취소와 지급 · 취소(제32조)","지급위탁의 취소는 제시기간이 지난 후에만 효력이 생기고 취소가 없으면 지급인은 제시기간이 지난 뒤에도 지급할 수 있다"],["지급위탁 취소와 지급 · 방식","지급위탁 취소는 수표행위가 아니어서 방식 제한이 없고 구두로도 할 수 있다"],["지급위탁 취소와 지급 · 사망·무능력","발행 후 발행인이 사망하거나 무능력자가 되어도 수표의 효력에는 영향이 없다(제33조)"],["지급위탁 취소와 지급 · 지급","소지인은 일부지급을 거절하지 못하며(제34조) 지급인은 배서의 연속만 조사하고 기명날인까지 조사할 의무는 없다(제35조)"],["횡선수표 · 종류(제37조)","발행인이나 소지인은 수표 앞면에 두 줄의 평행선을 그을 수 있고 안에 아무것도 없거나 「은행」을 적으면 일반횡선, 은행 명칭을 적으면 특정횡선이다"],["횡선수표 · 변경","일반횡선은 특정횡선으로 바꿀 수 있지만 특정횡선은 일반횡선으로 바꾸지 못하며 횡선이나 지정 은행 명칭을 말소해도 하지 않은 것으로 본다"],["횡선수표 · 일반횡선수표(제38조)","지급인은 은행이나 자기 거래처에만 지급하고 이를 어긴 지급인이나 은행은 수표금액 한도에서 손해를 배상한다"]]},{"t":"table","title":"지급보증 · 상환청구와 시효","head":["구분","내용"],"rows":[["지급보증 · 방식(제53조)","지급보증은 수표 앞면에 지급보증 등 지급하겠다는 뜻을 적고 날짜를 부기해 지급인이 기명날인하거나 서명하고 조건 없이 해야 하며 기재사항을 바꾼 부분은 바꾸지 않은 것으로 본다(제54조)"],["지급보증 · 효력","지급보증을 한 지급인은 제시기간이 지나기 전에 제시된 경우에만 지급의무를 지고 발행인 등은 지급보증으로 책임을 면하지 못하며(제55조·제56조) 금액 일부의 지급보증은 할 수 없다"],["지급보증 · 거절·시효","지급인이 지급보증을 거절해도 상환청구 사유가 되지 않고 지급보증인에 대한 청구권은 제시기간이 지난 후 1년의 시효로 소멸한다(제58조)"],["상환청구와 시효 · 증명(제39조)","제시기간 내에 제시했으나 지급받지 못한 소지인이 거절증서, 날짜를 부기한 지급인의 선언, 어음교환소의 선언 중 하나로 거절을 증명하면 배서인·발행인 등에게 상환청구할 수 있다"],["상환청구와 시효 · 작성 시기(제40조)","거절증서나 선언은 제시기간이 지나기 전에 작성시키고 말일에 제시했으면 다음 제1거래일에 작성시킬 수 있다"],["상환청구와 시효 · 시효(제51조)","소지인의 상환청구권은 제시기간이 지난 후 6개월, 채무자의 재상환청구권은 환수한 날이나 제소된 날부터 6개월의 시효로 소멸한다"]]}]};
